import{d as f,C as g,o as k,c as P,a3 as d,E as t,j as i,a as e}from"./chunks/framework.D4-ViStF.js";const G=JSON.parse('{"title":"庄子·应帝王","description":"从在宥天下、明王之治、壶子四示到浑沌之死，理解庄子无为而治的终极寓言。","frontmatter":{"title":"庄子·应帝王","description":"从在宥天下、明王之治、壶子四示到浑沌之死，理解庄子无为而治的终极寓言。","category":"guide","aliases":["应帝王","庄子应帝王","zhuangzi chapter 07"],"source":["《庄子》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-07.md","filePath":"daoism/zhuang-zi/chapter-07.md","lastUpdated":1788758894000}'),T={name:"daoism/zhuang-zi/chapter-07.md"},S=f({...T,setup(C){const y=[{id:"nie_s1",label:"啮缺问于王倪……行以告蒲衣子",sentences:[[{text:"啮缺",glossary:"nie_que"},"问于",{text:"王倪",glossary:"wang_ni"},"，四问而四不知。"],["啮缺",{text:"因跃而大喜",glossary:"yin_yue_xi"},"，行以告",{text:"蒲衣子",glossary:"pu_yi_zi"},"。"]]},{id:"nie_s2",label:"蒲衣子曰而乃今知之乎……而未始出于非人",sentences:[[{text:"蒲衣子",glossary:"pu_yi_zi"},"曰：「而乃今知之乎？"],[{text:"有虞氏",glossary:"you_yu_shi"},"不及",{text:"泰氏",glossary:"tai_shi"},"。"],["有虞氏其犹",{text:"藏仁以要人",glossary:"cang_ren_yao_ren"},"，",{text:"亦得人矣",glossary:"yi_de_ren"},"，而",{text:"未始",glossary:"wei_shi_cong"},{text:"出于非人",glossary:"chu_fei_ren"},"。"]]},{id:"nie_s3",label:"泰氏其卧徐徐……而未始入于非人",sentences:[["泰氏",{text:"其卧徐徐",glossary:"wo_xu_xu"},"，",{text:"其觉于于",glossary:"jue_yu_yu"},"。"],[{text:"一以己为马",glossary:"yi_ji_ma"},"，",{text:"一以己为牛",glossary:"yi_ji_niu"},"。"],[{text:"其知情信",glossary:"zhi_qing_xin"},"，",{text:"其德甚真",glossary:"de_shen_zhen"},"，而",{text:"未始",glossary:"wei_shi_cong"},{text:"入于非人",glossary:"ru_fei_ren"},"。」"]]}],l=[{id:"nie_que",term:"啮缺",pinyin:"niè quē",meaning:"人名，庄子虚构的求道者。啮缺：读 niè quē，《逍遥游》·《齐物论》中亦出现。此处向王倪四问而四不知，因王倪的「不知」而大喜——「不知」正是超越知识执着的体现。"},{id:"wang_ni",term:"王倪",pinyin:"wáng ní",meaning:"人名，庄子虚构的得道者，啮缺之师。王倪：读 wáng ní，四问四不知——以「不知」示道，超越知识的执着。"},{id:"yin_yue_xi",term:"因跃而大喜",pinyin:"yīn yuè ér dà xǐ",meaning:"于是跳跃起来大为欢喜。因：于是；跃：跳跃（喜不自禁的肢体反应）；大喜：非常欢喜。因跃而大喜：因王倪的「四不知」而跳跃大喜——「不知」即道，啮缺领悟到「知之为知之，不知为不知」之上还有更高的「不知」。"},{id:"pu_yi_zi",term:"蒲衣子",pinyin:"pú yī zǐ",meaning:"人名，庄子虚构的上古得道者。蒲衣子：读 pú yī zǐ，传说中的上古圣人，此处作为论道者，点出有虞氏不及泰氏的深层原因。"},{id:"you_yu_shi",term:"有虞氏",pinyin:"yǒu yú shì",meaning:"虞舜（传说中的圣君）。有虞氏：舜的称号，读 yǒu yú shì——儒家推崇的仁义圣王，此处被庄子以「不及泰氏」加以批评。"},{id:"tai_shi",term:"泰氏",pinyin:"tài shì",meaning:"上古的理想帝王（超越有虞氏的得道者）。泰氏：读 tài shì，传说中比舜更古远的帝王，庄子以之代表「无为而治」的最高境界——与有虞氏（仁义治世）相对，泰氏是超越仁义的自然之治。"},{id:"cang_ren_yao_ren",term:"藏仁以要人",pinyin:"cáng rén yǐ yāo rén",meaning:"收藏（运用）仁来笼络人心。藏：收藏、运用；仁：仁义；要：笼络、求取，读 yāo（通「邀」）；人：人心·众人。藏仁以要人：以仁义笼络人心——有虞氏（舜）以仁义治世，仁义是手段，目的是得人心，仍有「为」的痕迹。"},{id:"yi_de_ren",term:"亦得人矣",pinyin:"yì dé rén yǐ",meaning:"也确实得到了人心。亦：也、确实；得人：得到人心；矣：语气词。亦得人矣：确实得到了人心——肯定有虞氏的成效，但随即以「而未始出于非人」指出其局限。"},{id:"wei_shi_cong",term:"未始",pinyin:"wèi shǐ",meaning:"从未、始终未曾。未始：从来不曾、始终没有。未始出于非人·未始入于非人：两处「未始」对举，是本节核心对比的关键词。"},{id:"chu_fei_ren",term:"出于非人",pinyin:"chū yú fēi rén",meaning:"超出「非人」（的范畴）。出：超出、走出；非人：非人的境界（超越人为执着的自然境界）。而未始出于非人：却从未超出「非人」的范畴——有虞氏以仁义得人，仍在「人为」的层面，始终未能超越人为执着，进入自然无为的「非人」境界。"},{id:"wo_xu_xu",term:"其卧徐徐",pinyin:"qí wò xú xú",meaning:"他睡觉时舒缓自在（无所执着）。卧：睡觉；徐徐：舒缓、从容自在的样子。其卧徐徐：睡觉时舒缓自在——连睡眠都是自然无为的状态。"},{id:"jue_yu_yu",term:"其觉于于",pinyin:"qí jué yú yú",meaning:"他醒来时自得悠然（无所拘束）。觉：醒来；于于：自得悠然、无所拘束的样子，读 yú yú。其觉于于：醒来时自得悠然——醒时同样是自然无为的状态。其卧徐徐·其觉于于：睡与醒皆自然，无论何种状态皆顺应自然——与有虞氏「藏仁以要人」的刻意形成鲜明对比。"},{id:"yi_ji_ma",term:"一以己为马",pinyin:"yī yǐ jǐ wéi mǎ",meaning:"（有人）称他为马，他就以自己为马（顺应接受）。一：有时、或者（副词）；以己为马：以自己为马（顺应他人的称呼）。一以己为马：有时（被人称为马）就以自己为马——完全顺应外界的定义，无自我执着。"},{id:"yi_ji_niu",term:"一以己为牛",pinyin:"yī yǐ jǐ wéi niú",meaning:"（有人）称他为牛，他就以自己为牛（顺应接受）。一以己为牛：有时（被人称为牛）就以自己为牛——同样顺应。一以己为马·一以己为牛：两句并举，以「马」「牛」两种截然不同的称呼，说明泰氏完全超越了自我定义的执着——无论被如何称呼，皆顺应接受，无「我」可执。"},{id:"zhi_qing_xin",term:"其知情信",pinyin:"qí zhī qíng xìn",meaning:"他的智慧是真实可信的（出于本真）。知：智慧；情：真实、实情；信：可信、诚信。其知情信：他的智慧真实可信——非刻意造作，而是出于本真自然。"},{id:"de_shen_zhen",term:"其德甚真",pinyin:"qí dé shèn zhēn",meaning:"他的德性极为纯真（出于本性）。德：德性；甚：极为；真：纯真、本真。其德甚真：他的德性极为纯真——非仁义的外在标榜，而是本性自然流露。其知情信·其德甚真：知（智慧）与德（德性）皆出于本真——与有虞氏「藏仁以要人」的刻意相对，泰氏的知与德皆是自然本真，无需「藏」与「要」。"},{id:"ru_fei_ren",term:"入于非人",pinyin:"rù yú fēi rén",meaning:"落入「非人」（的执着）。入：落入、陷入；非人：非人的执着（被外界的「非人」评价所动）。而未始入于非人：却从未落入「非人」的执着——泰氏无论被称为马还是牛，从未因「非人」的称呼而动摇，始终保持本真。出于非人·入于非人：两个「非人」对举，意思相反——有虞氏「未始出于非人」（始终未能超越人为），泰氏「未始入于非人」（始终未曾落入非人的执着）——一个困于「人为」，一个超越「非人」，境界高下立判。"}],o=[{id:"jie_s1",label:"肩吾见狂接舆……告我君人者以己出经式义度",sentences:[[{text:"肩吾",glossary:"jian_wu"},"见",{text:"狂接舆",glossary:"kuang_jie_yu"},"。狂接舆曰：「",{text:"日中始",glossary:"ri_zhong_shi"},{text:"何以语女",glossary:"he_yu_ru"},"？」"],["肩吾曰：「",{text:"告我",glossary:"gao_wo"},"：",{text:"君人者",glossary:"jun_ren_zhe"},{text:"以己",glossary:"yi_ji_chu"},{text:"出经式义度",glossary:"chu_jing_shi_yi_du"},"，人孰敢不听而",{text:"化诸",glossary:"hua_zhu"},"！」"]]},{id:"jie_s2",label:"狂接舆曰是欺德也……而使蚊负山也",sentences:[["狂接舆曰：「是",{text:"欺德也",glossary:"qi_de"},"。"],["其于治天下也，犹",{text:"涉海凿河",glossary:"she_hai_zao_he"},"而使",{text:"蚊负山",glossary:"wen_fu_shan"},"也。"]]},{id:"jie_s3",label:"夫圣人之治也……确乎能其事者而已矣",sentences:[["夫圣人之治也，",{text:"治外夫",glossary:"zhi_wai_fu"},"？"],[{text:"正而后行",glossary:"zheng_hou_xing"},"，",{text:"确乎",glossary:"que_hu"},{text:"能其事者",glossary:"neng_qi_shi"},{text:"而已矣",glossary:"er_yi_yi"},"。"]]},{id:"jie_s4",label:"且鸟高飞以避矰弋之害……而曾二虫之无知",sentences:[["且鸟高飞以",{text:"避矰弋之害",glossary:"bi_zeng_yi"},"，"],["鼷鼠深穴乎",{text:"神丘之下",glossary:"shen_qiu"},"以",{text:"避熏凿之患",glossary:"bi_xun_zao"},"，"],["而",{text:"曾二虫之无知",glossary:"zeng_er_chong"},"？」"]]}],_=[{id:"jian_wu",term:"肩吾",pinyin:"jiān wú",meaning:"人名，庄子虚构的求道者。肩吾：读 jiān wú，《逍遥游》中亦出现。此处作为日中始教化的听受者，向狂接舆转述——代表对儒家治世之道尚有疑惑的人。"},{id:"kuang_jie_yu",term:"狂接舆",pinyin:"kuáng jiē yú",meaning:"楚国的隐士，佯狂避世的得道者。狂接舆：读 kuáng jiē yú，《论语》中曾唱「凤兮凤兮」讽孔子，此处作为批评儒家治世之道的代言人——以「狂」的姿态道出最清醒的批判。"},{id:"ri_zhong_shi",term:"日中始",pinyin:"rì zhōng shǐ",meaning:"人名，庄子虚构的人物（肩吾的对话者）。日中始：读 rì zhōng shǐ，此处作为「君人者以己出经式义度」观点的持有者——代表儒家治世主张的一方。"},{id:"he_yu_ru",term:"何以语女",pinyin:"hé yǐ yǔ rǔ",meaning:"（日中始）用什么话告诉你？何以：用什么；语：告诉、对……说；女：通「汝」，你。何以语女：日中始对你说了什么？"},{id:"gao_wo",term:"告我",pinyin:"gào wǒ",meaning:"（他）告诉我（说）。告：告诉；我：我（肩吾）。告我：他告诉我——引出日中始的主张。"},{id:"jun_ren_zhe",term:"君人者",pinyin:"jūn rén zhě",meaning:"统治人（治理天下）的人（君主）。君人：统治人、为人君；者：……的人。君人者：君主、统治者——儒家治世的主体。"},{id:"yi_ji_chu",term:"以己",pinyin:"yǐ jǐ",meaning:"凭借自己（的标准）。以：凭借；己：自己。以己出经式义度：凭借自己（的标准）制定法则规范——「以己」点出问题所在：以一己之标准强加于天下。"},{id:"chu_jing_shi_yi_du",term:"出经式义度",pinyin:"chū jīng shì yì dù",meaning:"制定（颁布）法则·规式·义理·法度。出：制定、颁布；经：经典法则；式：规式、规范；义：义理、道义；度：法度、尺度。出经式义度：制定一整套法则规范义度——以「经·式·义·度」四字并举，描绘儒家治世的全套规范体系。"},{id:"hua_zhu",term:"化诸",pinyin:"huà zhū",meaning:"被（它）教化（顺从）。化：被教化、顺从；诸：之（代词，代指经式义度）。人孰敢不听而化诸：人们谁敢不听从而被它教化——日中始认为以己出经式义度，天下自然顺从。"},{id:"qi_de",term:"欺德也",pinyin:"qī dé yě",meaning:"是欺骗（违背）德性啊。欺：欺骗、违背；德：本真的德性；也：语气词。是欺德也：这是欺骗德性——狂接舆对「以己出经式义度」的直接批判：以一己标准强加于天下，是对天下万物本真德性的欺骗与违背。"},{id:"she_hai_zao_he",term:"涉海凿河",pinyin:"shè hǎi záo hé",meaning:"徒步涉过大海·凿通河道（不可能完成的事）。涉海：徒步渡海；凿河：开凿河道。涉海凿河：以人力强行完成不可能之事——喻以己出经式义度治天下，是强行以人力干预自然，徒劳无功。"},{id:"wen_fu_shan",term:"蚊负山",pinyin:"wén fù shān",meaning:"让蚊子背负大山（力不胜任之事）。蚊：蚊子；负：背负；山：大山。蚊负山：以蚊子之微力背负大山——喻以人为之力强行治理天下，完全超出能力范围。涉海凿河·蚊负山：两个极端意象并举，以荒诞的夸张说明「以己出经式义度」治天下的不可能——强行为之，只是徒劳。"},{id:"zhi_wai_fu",term:"治外夫",pinyin:"zhì wài fū",meaning:"（圣人的治理）是治理外在（形式）吗？治外：治理外在（形式·规范）；夫：语气词，表反问，读 fū。夫圣人之治也，治外夫：圣人的治理，难道是治理外在形式吗？——以反问否定「以己出经式义度」的外在治理，引出「正而后行」的内在治理。"},{id:"zheng_hou_xing",term:"正而后行",pinyin:"zhèng ér hòu xíng",meaning:"（使自己）端正之后再行动。正：端正（自身）；而后：然后；行：行动。正而后行：先正己，后行事——圣人之治的核心：不是向外制定规范，而是向内端正自身，自然而然地感化。"},{id:"que_hu",term:"确乎",pinyin:"què hū",meaning:"确实、切实（副词，表坚定确实）。确乎：确实、切实地。确乎能其事者：确实能够胜任其事的人——圣人之治，只是确实做好自己能做的事。"},{id:"neng_qi_shi",term:"能其事者",pinyin:"néng qí shì zhě",meaning:"能够胜任其事的人（做好自己分内之事）。能：能够胜任；其事：他自己的事；者：……的人。确乎能其事者而已矣：确实能够胜任自己分内之事，仅此而已——圣人之治不是强加规范，而是各尽其能，顺应自然。"},{id:"er_yi_yi",term:"而已矣",pinyin:"ér yǐ yǐ",meaning:"仅此而已（表限定，不过如此）。而已：仅此；矣：语气词。确乎能其事者而已矣：确实能胜任自己之事，仅此而已——以「而已矣」收束，点出圣人之治的简洁本质：无需经式义度，只需正己·能事。"},{id:"bi_zeng_yi",term:"避矰弋之害",pinyin:"bì zēng yì zhī hài",meaning:"躲避矰弋（射猎工具）的伤害。矰：系有丝绳的箭，用于射鸟，读 zēng；弋：带绳的箭，读 yì；之害：的伤害。鸟高飞以避矰弋之害：鸟高飞来躲避弓箭的伤害——鸟自知危险，以本能自保。"},{id:"shen_qiu",term:"神丘之下",pinyin:"shén qiū zhī xià",meaning:"神圣之丘（社坛）的下面。神丘：神圣的土丘，指社坛（祭祀土地神之处）；之下：的下面。鼷鼠深穴乎神丘之下：鼷鼠在社坛下深挖洞穴——神丘之下因神圣而不被轻易挖掘，鼷鼠以此自保。"},{id:"bi_xun_zao",term:"避熏凿之患",pinyin:"bì xūn záo zhī huàn",meaning:"躲避烟熏·挖凿的祸患。熏：烟熏（驱鼠）；凿：挖凿（掘穴）；之患：的祸患。避熏凿之患：躲避人类用烟熏·挖凿驱逐的祸患——鼷鼠以深穴于神丘之下自保。"},{id:"zeng_er_chong",term:"曾二虫之无知",pinyin:"zēng èr chóng zhī wú zhī",meaning:"难道这两种小虫没有智慧吗？曾：难道（表反问，读 zēng）；二虫：两种小动物（鸟与鼷鼠）；之：助词；无知：没有智慧。而曾二虫之无知：难道这两种小虫没有智慧吗？——以反问点出：鸟与鼷鼠皆知自保，各顺其性，远胜「以己出经式义度」的强行治世。以鸟·鼷鼠的本能自保，反讽以己出经式义度的「圣人」：连小虫都知道顺应自然自保，强行治世者反而不如。"}],m=[{id:"tian_s1",label:"天根游于殷阳……适遭无名人而问焉",sentences:[[{text:"天根",glossary:"tian_gen"},"游于",{text:"殷阳",glossary:"yin_yang_di"},"，至",{text:"蓼水",glossary:"liao_shui"},"之上，适遭",{text:"无名人",glossary:"wu_ming_ren"},"而问焉，曰：「",{text:"请问为天下",glossary:"qing_wen_wei_tianxia"},"。」"]]},{id:"tian_s2",label:"无名人曰去……以处圹埌之野",sentences:[["无名人曰：「",{text:"去",glossary:"qu_li_kai"},"！",{text:"汝鄙人也",glossary:"ru_bi_ren"},"，",{text:"何问之不豫也",glossary:"he_wen_bu_yu"},"！"],[{text:"予",glossary:"yu_wo"},{text:"方",glossary:"fang_zhengzai"},{text:"将",glossary:"jiang_jijiang"},"与造物者为人，"],[{text:"厌则又乘夫",glossary:"yan_ze_cheng_fu"},{text:"莽眇之鸟",glossary:"mang_miao_niao"},"，以出",{text:"六极之外",glossary:"liu_ji_wai"},"，"],["而游",{text:"无何有之乡",glossary:"wu_he_you_xiang"},"，以",{text:"处圹埌之野",glossary:"kuang_lang_ye"},"。"]]},{id:"tian_s3",label:"汝又何帛以治天下感予之心为……又复问",sentences:[[{text:"汝又何帛",glossary:"he_bo_gan"},"以治天下",{text:"感予之心为",glossary:"gan_yu_xin"},"？」"],["又复问，"]]},{id:"tian_s4",label:"无名人曰汝游心于淡……而天下治矣",sentences:[["无名人曰：「汝",{text:"游心于淡",glossary:"you_xin_dan"},"，",{text:"合气于漠",glossary:"he_qi_mo"},"，"],[{text:"顺物自然",glossary:"shun_wu_ziran"},"而",{text:"无容私焉",glossary:"wu_rong_si"},"，而",{text:"天下治矣",glossary:"tianxia_zhi"},"。」"]]}],h=[{id:"tian_gen",term:"天根",pinyin:"tiān gēn",meaning:"人名，庄子虚构的求道者。天根：读 tiān gēn，以「天根」为名，暗示其追问天道根本——此处向无名人问「为天下」之道。"},{id:"yin_yang_di",term:"殷阳",pinyin:"yīn yáng",meaning:"地名，殷山的南面（阳面）。殷：山名；阳：山的南面（古代山南为阳）。天根游于殷阳：天根游历于殷山南面——以游历起笔，引出偶遇无名人的场景。"},{id:"liao_shui",term:"蓼水",pinyin:"liǎo shuǐ",meaning:"水名，庄子虚构的地名。蓼水：读 liǎo shuǐ，虚构的水名——与殷阳并列，构成游历的自然背景，无需坐实。"},{id:"wu_ming_ren",term:"无名人",pinyin:"wú míng rén",meaning:"无名之人（超越名称与身份的得道者）。无名人：没有名字的人——以「无名」点出其超越世俗名分的境界，呼应「无名」即道的主题。"},{id:"qing_wen_wei_tianxia",term:"请问为天下",pinyin:"qǐng wèn wéi tiān xià",meaning:"请问如何治理天下。请问：请教；为天下：治理天下。请问为天下：请教治理天下之道——天根的问题是儒家政治的核心命题，无名人以「去！汝鄙人也」回应，彻底否定这一问题的出发点。"},{id:"qu_li_kai",term:"去",pinyin:"qù",meaning:"走开、离去（表拒绝·驱斥）。去：走开。去！汝鄙人也：走开！你这鄙陋之人——无名人以强烈的驱斥开场，非真的驱赶，而是点出天根问题本身的鄙陋（执着于「治天下」）。"},{id:"ru_bi_ren",term:"汝鄙人也",pinyin:"rǔ bǐ rén yě",meaning:"你是鄙陋之人啊。鄙人：见识浅陋的人；也：判断语气。汝鄙人也：你是见识浅陋的人——非人身攻击，而是指天根执着于「治天下」，见识局限于世俗层面。"},{id:"he_wen_bu_yu",term:"何问之不豫也",pinyin:"hé wèn zhī bù yù yě",meaning:"为何问的问题如此令人不快（不合时宜）啊！何：为何；不豫：不快、令人不悦，读 yù；也：语气词。何问之不豫也：为何所问的问题如此令人不快——无名人嫌天根的问题俗陋，不合道的境界。"},{id:"yu_wo",term:"予",pinyin:"yǔ",meaning:"我（第一人称代词）。予：我，读 yǔ。予方将与造物者为人：我正将要与造物者同游——无名人自述其所处的境界，与「治天下」的世俗关怀形成鲜明对比。"},{id:"fang_zhengzai",term:"方",pinyin:"fāng",meaning:"正在、正（副词，表当下进行）。方：正在。予方将：我正将要——「方」与「将」叠用，强调无名人当下正处于即将出游的状态。"},{id:"jiang_jijiang",term:"将",pinyin:"jiāng",meaning:"将要（副词，表即将）。将：将要。方将：正将要——两字叠用，强调即将性，衬托无名人对「治天下」之问的不耐。"},{id:"yan_ze_cheng_fu",term:"厌则又乘夫",pinyin:"yàn zé yòu chéng fū",meaning:"（游够了）厌倦了便又乘上那（莽眇之鸟）。厌：厌倦、满足（游够了）；则：便；又：又；乘：乘骑；夫：那（指示词）。厌则又乘夫莽眇之鸟：游够了便又乘上那莽眇之鸟——描绘无名人在造物者之游与莽眇之鸟之游之间自在往返，无所拘束。"},{id:"mang_miao_niao",term:"莽眇之鸟",pinyin:"mǎng miǎo zhī niǎo",meaning:"广漠渺远之鸟（超越形体的精神之鸟）。莽：广漠、无边；眇：渺远、微妙，读 miǎo；之鸟：的鸟。莽眇之鸟：广漠渺远的鸟——非实指，而是精神自由遨游的象征，呼应《逍遥游》的鲲鹏意象。"},{id:"liu_ji_wai",term:"六极之外",pinyin:"liù jí zhī wài",meaning:"六极（宇宙六方极限）之外。六极：上下四方六个方向的极限，即宇宙的边界；之外：之外。出六极之外：超出宇宙边界之外——超越一切空间限制，游于无限之境。"},{id:"wu_he_you_xiang",term:"无何有之乡",pinyin:"wú hé yǒu zhī xiāng",meaning:"什么都没有的地方（虚无之境）。无何有：什么都没有；之乡：的地方。无何有之乡：虚无之乡——《逍遥游》中亦出现，指超越一切存在的虚无之境，是道的象征性居所。"},{id:"kuang_lang_ye",term:"处圹埌之野",pinyin:"chǔ kuàng làng zhī yě",meaning:"居处于广漠空旷的原野。圹埌：广漠空旷，读 kuàng làng；之野：的原野。处圹埌之野：居处于广漠空旷的原野——与「无何有之乡」并列，共同描绘无名人所游的虚无广漠之境。无何有之乡·圹埌之野：两个意象并举，一「乡」一「野」，皆是超越世俗的虚无之境——无名人所游之处，远非「治天下」的世俗关怀所能及。"},{id:"he_bo_gan",term:"汝又何帛",pinyin:"rǔ yòu hé bó",meaning:"你又凭什么（用什么）。何帛：通「何以」，凭什么、用什么，读 hé bó（帛通「魄」或作语气助词）。汝又何帛以治天下感予之心为：你又凭什么用治天下（的问题）来打扰我的心？"},{id:"gan_yu_xin",term:"感予之心为",pinyin:"gǎn yǔ zhī xīn wéi",meaning:"打扰（触动）我的心呢？感：打扰、触动；予之心：我的心；为：语气词，表反问。汝又何帛以治天下感予之心为：你又凭什么用治天下来打扰我的心呢？——无名人拒绝被「治天下」的世俗问题所动，其心游于淡漠之境，不受外物干扰。"},{id:"you_xin_dan",term:"游心于淡",pinyin:"yóu xīn yú dàn",meaning:"让心游于恬淡（无执着）之中。游心：让心自由游荡；于淡：在恬淡之中。游心于淡：心游于恬淡——超越一切好恶执着，心境恬淡自然。"},{id:"he_qi_mo",term:"合气于漠",pinyin:"hé qì yú mò",meaning:"使气与虚漠（自然）相合。合气：使气（元气·精气）相合；于漠：与虚漠（自然无为）。合气于漠：使气与虚漠自然相合——超越一切人为造作，气与自然浑然一体。游心于淡·合气于漠：心（精神）与气（生命）并举，一「游」一「合」——精神恬淡，生命与自然相合，是治天下的内在根基。"},{id:"shun_wu_ziran",term:"顺物自然",pinyin:"shùn wù zì rán",meaning:"顺应万物的自然本性。顺：顺应；物：万物；自然：自然本性、本来如此。顺物自然：顺应万物各自的自然本性——不以己意强加，任万物自然发展。"},{id:"wu_rong_si",term:"无容私焉",pinyin:"wú róng sī yān",meaning:"不容纳（不掺入）任何私心。无：不；容：容纳、掺入；私：私心、个人偏见；焉：语气词。无容私焉：不掺入任何私心——顺物自然的前提是无私，无私方能真正顺应万物。顺物自然·无容私焉：两句并举，「顺物」是方向，「无私」是条件——顺应万物自然，不掺私心，天下自然得治。"},{id:"tianxia_zhi",term:"天下治矣",pinyin:"tiān xià zhì yǐ",meaning:"天下就治理好了。治：治理好、安定；矣：语气词，表自然结果。而天下治矣：天下便自然治理好了——以「而」字点出因果：游心于淡·合气于漠·顺物自然·无容私焉，四者具备，天下自然得治，无需「以己出经式义度」的刻意为之。"}],u=[{id:"yang_s1",label:"阳子居见老聃……如是者可比明王乎",sentences:[[{text:"阳子居",glossary:"yang_zi_ju"},"见",{text:"老聃",glossary:"lao_dan"},"，曰：「有人于此，"],[{text:"向疾强梁",glossary:"xiang_ji_qiang_liang"},"，",{text:"物彻疏明",glossary:"wu_che_shu_ming"},"，",{text:"学道不倦",glossary:"xue_dao_bu_juan"},"，"],["如是者，可",{text:"比",glossary:"bi_pinjiao"},{text:"明王",glossary:"ming_wang"},"乎？」"]]},{id:"yang_s2",label:"老聃曰是於圣人也……猨狙之便执嫠之狗来藉",sentences:[["老聃曰：「是於圣人也，",{text:"胥易技系",glossary:"xu_yi_ji_xi"},"，",{text:"劳形怵心者也",glossary:"lao_xing_chu_xin"},"。"],["且也",{text:"虎豹之文来田",glossary:"hu_bao_wen_tian"},"，",{text:"猨狙之便",glossary:"yuan_ju_bian"},{text:"执嫠之狗",glossary:"zhi_li_gou"},{text:"来藉",glossary:"lai_ji"},"。"],[{text:"如是者",glossary:"ru_shi_zhe"},"，可比明王乎？」"]]},{id:"yang_s3",label:"阳子居蹴然曰……明王之治",sentences:[["阳子居",{text:"蹴然",glossary:"cu_ran_yang"},"曰：「敢问",{text:"明王之治",glossary:"ming_wang_zhi"},"。」"]]},{id:"yang_s4",label:"老聃曰明王之治……立乎不测而游于无有者也",sentences:[["老聃曰：「明王之治：",{text:"功盖天下",glossary:"gong_gai_tianxia"},"而似不自己，"],[{text:"化贷万物",glossary:"hua_dai_wanwu"},"而",{text:"民弗恃",glossary:"min_fu_shi"},"。"],[{text:"有莫举名",glossary:"you_mo_ju_ming"},"，",{text:"使物自喜",glossary:"shi_wu_zi_xi"},"。"],[{text:"立乎不测",glossary:"li_bu_ce"},"，而",{text:"游于无有者也",glossary:"you_wu_you"},"。」"]]}],p=[{id:"yang_zi_ju",term:"阳子居",pinyin:"yáng zǐ jū",meaning:"人名，庄子虚构的求道者（或指杨朱）。阳子居：读 yáng zǐ jū，此处以「有人于此」描述一个才德出众之人，向老聃询问是否可比明王——代表以才智·勤学自许的世俗贤人观。"},{id:"lao_dan",term:"老聃",pinyin:"lǎo dān",meaning:"老子（道家始祖）。老聃：老子的名，读 lǎo dān——庄子借老子之口阐发明王之治的道家理想，以「无为」否定才智勤学的世俗贤王观。"},{id:"xiang_ji_qiang_liang",term:"向疾强梁",pinyin:"xiàng jí qiáng liáng",meaning:"意志敏锐坚强有力。向疾：意志敏锐、反应迅捷；强梁：强健有力、刚强。向疾强梁：意志敏锐、刚强有力——描绘世俗贤王的第一种才能：意志力与行动力。"},{id:"wu_che_shu_ming",term:"物彻疏明",pinyin:"wù chè shū míng",meaning:"洞彻事物、思维疏朗明达。物彻：洞彻事物；疏明：思维疏朗、明达通透。物彻疏明：洞察事物、明达通透——描绘世俗贤王的第二种才能：智识与洞察力。"},{id:"xue_dao_bu_juan",term:"学道不倦",pinyin:"xué dào bù juàn",meaning:"学习道（知识）不知疲倦。学道：学习道（知识·道理）；不倦：不疲倦。学道不倦：勤学不倦——描绘世俗贤王的第三种才能：勤勉好学。向疾强梁·物彻疏明·学道不倦：三者并举，构成世俗眼中完美贤王的形象——意志·智识·勤学，恰是儒家推崇的君王品质。"},{id:"bi_pinjiao",term:"比",pinyin:"bǐ",meaning:"比拟、媲美。比：比较、媲美。可比明王乎：可以媲美明王吗？——阳子居以世俗贤才标准衡量明王，老聃随即否定这一标准。"},{id:"ming_wang",term:"明王",pinyin:"míng wáng",meaning:"圣明的帝王（道家理想中的无为之王）。明王：圣明的王——本节核心概念，老聃所论明王之治，与世俗贤王（才智勤学）截然不同，是「功盖天下而似不自己」的无为之王。"},{id:"xu_yi_ji_xi",term:"胥易技系",pinyin:"xū yì jì xì",meaning:"不过是小吏的技艺所束缚（的层次）。胥：小吏、胥吏，读 xū；易：轻易、平常；技：技艺；系：束缚、拘系。胥易技系：不过是小吏层面的技艺束缚——老聃以「胥易」（小吏）贬低向疾强梁·物彻疏明·学道不倦，指出这些不过是技艺层面的执着，非明王之道。"},{id:"lao_xing_chu_xin",term:"劳形怵心者也",pinyin:"láo xíng chù xīn zhě yě",meaning:"劳累形体、惊扰内心的人啊。劳形：劳累形体；怵心：惊扰内心，读 chù；者也：……的人啊。劳形怵心者也：劳累形体·惊扰内心的人——以「劳形怵心」点出世俗贤才的根本问题：刻意为之，反而劳形伤心，与道背道而驰。"},{id:"hu_bao_wen_tian",term:"虎豹之文来田",pinyin:"hǔ bào zhī wén lái tián",meaning:"虎豹因（身上的）花纹而招来猎人。文：花纹、斑纹；来田：招来田猎（猎人前来猎取）；田：通「畋」，田猎、打猎。虎豹之文来田：虎豹因花纹美丽而招来猎人——以虎豹之文喻才智出众者反因才能而招祸。"},{id:"yuan_ju_bian",term:"猨狙之便",pinyin:"yuán jū zhī biàn",meaning:"猿猴的灵便（敏捷）。猨狙：猿猴，读 yuán jū；之便：的灵便、敏捷。猨狙之便：猿猴的灵便敏捷——以猿猴之便喻才能出众者。"},{id:"zhi_li_gou",term:"执嫠之狗",pinyin:"zhí lí zhī gǒu",meaning:"（招来）执绳之狗（猎狗被牵来追捕）。执嫠：执绳、牵绳，读 lí；之狗：的狗（猎狗）。执嫠之狗：牵绳的猎狗——猎人牵猎狗来追捕猿猴。"},{id:"lai_ji",term:"来藉",pinyin:"lái jí",meaning:"招来（猎人）前来捕捉。藉：通「籍」，捕捉、拘押，读 jí。猨狙之便执嫠之狗来藉：猿猴因灵便而招来猎狗前来捕捉——与虎豹之文来田并举，说明才能出众反而招祸。虎豹之文来田·猨狙之便执嫠之狗来藉：两个动物意象并举——虎豹因文（才华外露）招猎，猿猴因便（才能出众）招捕，以此警示：才智出众·刻意表现，反而招来祸患，非明王之道。"},{id:"ru_shi_zhe",term:"如是者",pinyin:"rú shì zhě",meaning:"像这样的（人）。如是：像这样；者：的人。如是者，可比明王乎：像这样（才能出众却招祸）的人，可以媲美明王吗？——老聃以反问收束，彻底否定才智出众者可比明王的观点。"},{id:"cu_ran_yang",term:"蹴然",pinyin:"cù rán",meaning:"惊讶肃然的样子（震惊而恭敬）。蹴：惊动、震惊，读 cù；然：……的样子。阳子居蹴然：阳子居震惊肃然——被老聃的批评所震动，转而恭敬请教明王之治。"},{id:"ming_wang_zhi",term:"明王之治",pinyin:"míng wáng zhī zhì",meaning:"明王的治理之道。明王：圣明的帝王；之治：的治理。敢问明王之治：请问明王的治理之道——阳子居被否定后，转而虚心请教，引出老聃对明王之治的正面阐述。"},{id:"gong_gai_tianxia",term:"功盖天下",pinyin:"gōng gài tiān xià",meaning:"功绩覆盖（遍及）天下。功：功绩；盖：覆盖、遍及。功盖天下而似不自己：功绩遍及天下却好像不是出于自己——明王有大功却不居功，「似不自己」是无为的体现。"},{id:"hua_dai_wanwu",term:"化贷万物",pinyin:"huà dài wàn wù",meaning:"教化施予万物（使万物得到化育）。化：教化、化育；贷：施予、给予。化贷万物：教化施予万物——明王的化育遍及万物，如同天地自然。"},{id:"min_fu_shi",term:"民弗恃",pinyin:"mín fú shì",meaning:"百姓不（感到）依赖（他）。民：百姓；弗：不；恃：依赖、仰赖。化贷万物而民弗恃：化育万物而百姓不感到依赖——明王的化育如此自然，百姓不觉得是受人恩惠，呼应老子「功成而弗居」。"},{id:"you_mo_ju_ming",term:"有莫举名",pinyin:"yǒu mò jǔ míng",meaning:"（功德）有却无从举出名称。有：有（功德）；莫举名：无从举出名称、无法命名。有莫举名：有功德却无法命名——明王之功超越名称，无法以任何名称标榜，呼应「道可道，非常道」。"},{id:"shi_wu_zi_xi",term:"使物自喜",pinyin:"shǐ wù zì xǐ",meaning:"使万物各自欢喜（顺其自然）。使：使得；物：万物；自喜：自然欢喜、各得其所。使物自喜：使万物各自欢喜——明王不强加于物，万物在其治下各得其所，自然欢喜。有莫举名·使物自喜：无名而有实，不居功而万物自喜——明王之治的核心：无为而无不为。"},{id:"li_bu_ce",term:"立乎不测",pinyin:"lì hū bù cè",meaning:"立身于深不可测（的道）之中。立：立身、处身；乎：于；不测：深不可测（的道）。立乎不测：立身于深不可测的道之中——明王的根基是道，深不可测，无法以世俗标准衡量。"},{id:"you_wu_you",term:"游于无有者也",pinyin:"yóu yú wú yǒu zhě yě",meaning:"遨游于虚无（无为）之境的人啊。游：遨游；于无有：在虚无（无为）之境；者也：……的人啊。游于无有者也：遨游于虚无之境的人——明王不执着于任何有形的功名，遨游于无为虚无之境。立乎不测·游于无有者也：一「立」一「游」，立于道之深不可测，游于无为虚无之境——明王之治的终极境界，与「以己出经式义度」的外在强制形成根本对立。"}],x=[{id:"hu_s1",label:"郑有神巫曰季咸……尝试与来以予示之",sentences:[["郑有",{text:"神巫",glossary:"shen_wu"},"曰",{text:"季咸",glossary:"ji_xian"},"，知人之死生·存亡·祸福·寿夭，",{text:"期以",glossary:"qi_yi"},"岁月旬日若神。"],["郑人见之，皆",{text:"弃",glossary:"qi_tao"},"而走。"],[{text:"列子",glossary:"lie_zi"},"见之而心醉，归，以告",{text:"壶子",glossary:"hu_zi"},"，曰：「始吾以夫子之道为至矣，则又",{text:"有至焉者矣",glossary:"you_zhi_zhe"},"。」"],["壶子曰：「吾与汝",{text:"既其文",glossary:"ji_qi_wen"},"，",{text:"未既其实",glossary:"wei_ji_shi"},"。",{text:"而固得道与",glossary:"er_gu_de_dao"},"？"],["众雌而无雄，",{text:"而又奚卵焉",glossary:"xi_luan"},"！"],["而以道与",{text:"世亢",glossary:"shi_kang"},"，必信，夫故使人",{text:"得而相汝",glossary:"de_xiang_ru"},"。"],[{text:"尝试与来",glossary:"chang_shi_yu_lai"},"，",{text:"以予示之",glossary:"yi_yu_shi_zhi"},"。」"]]},{id:"hu_s2",label:"明日列子与之见壶子（第一示·地文·杜德机）……尝又与来",sentences:[["明日，列子与之见壶子。出而谓列子曰：「嘻！子之先生死矣！弗活矣！",{text:"不以旬数矣",glossary:"bu_xun_shu"},"！"],[{text:"吾见怪焉",glossary:"jian_guai"},"，",{text:"见湿灰焉",glossary:"jian_shi_hui"},"。」"],["列子入，",{text:"泣涕沾襟",glossary:"qi_ti_zhan_jin"},"以告壶子。"],["壶子曰：「",{text:"乡吾示之",glossary:"xiang_shi_zhi"},"以",{text:"地文",glossary:"di_wen"},"，",{text:"萌乎",glossary:"meng_hu"},{text:"不震不正",glossary:"bu_zhen_bu_zheng"},"，是",{text:"殆",glossary:"dai_gai"},"见吾",{text:"杜德机也",glossary:"du_de_ji"},"。",{text:"尝又与来",glossary:"chang_you_yu_lai"},"。」"]]},{id:"hu_s3",label:"明日又与之见壶子（第二示·天壤·善者机）……尝又与来",sentences:[["明日，又与之见壶子。出而谓列子曰：「",{text:"幸矣",glossary:"xing_yi"},"！子之先生遇我也，",{text:"有瘳矣",glossary:"you_chou"},"！",{text:"全然",glossary:"quan_ran"},"有生矣！吾见其",{text:"杜权矣",glossary:"du_quan"},"！」"],["列子入，以告壶子。壶子曰：「",{text:"乡吾示之",glossary:"xiang_shi_zhi"},"以",{text:"天壤",glossary:"tian_rang"},"，",{text:"名实不入",glossary:"ming_shi_bu_ru"},"，而",{text:"机发于踵",glossary:"ji_fa_zhong"},"。是",{text:"殆",glossary:"dai_gai"},"见吾",{text:"善者机也",glossary:"shan_zhe_ji"},"。尝又与来。」"]]},{id:"hu_s4",label:"明日又与之见壶子（第三示·太冲莫胜·衡气机）……尝又与来",sentences:[["明日，又与之见壶子。出而谓列子曰：「子之先生",{text:"不齐",glossary:"bu_qi_xin"},"，吾",{text:"无得而相焉",glossary:"wu_de_xiang"},"。",{text:"试齐",glossary:"shi_zhai"},"，且",{text:"复相之",glossary:"fu_xiang_zhi"},"。」"],["列子入，以告壶子。壶子曰：「吾乡示之以",{text:"太冲莫胜",glossary:"tai_chong_mo_sheng"},"，是",{text:"殆",glossary:"dai_gai"},"见吾",{text:"衡气机也",glossary:"heng_qi_ji"},"。"],[{text:"鲵桓之审为渊",glossary:"ni_huan_yuan"},"，",{text:"止水之审为渊",glossary:"zhi_shui_yuan"},"，",{text:"流水之审为渊",glossary:"liu_shui_yuan"},"。"],[{text:"渊有九名",glossary:"yuan_jiu_ming"},"，此处三焉。尝又与来。」"]]},{id:"hu_s5",label:"明日又与之见壶子（第四示·未始出吾宗）……故逃也",sentences:[["明日，又与之见壶子。",{text:"立未定",glossary:"li_wei_ding"},"，",{text:"自失而走",glossary:"zi_shi_zou"},"。"],["壶子曰：「追之！」列子",{text:"追之不及",glossary:"zhui_bu_ji"},"。反，以报壶子曰：「已",{text:"灭",glossary:"mie_shi_zong"},"矣，已",{text:"失",glossary:"mie_shi_zong"},"矣，吾弗及已。」"],["壶子曰：「乡吾示之以",{text:"未始出吾宗",glossary:"wei_shi_chu_zong"},"。吾与之",{text:"虚而委蛇",glossary:"xu_wei_yi"},"，不知其谁何，",{text:"因以为弟靡",glossary:"yin_di_mi"},"，",{text:"因以为波流",glossary:"yin_bo_liu"},"，故逃也。」"]]},{id:"hu_s6",label:"然后列子自以为未始学而归……一以是终",sentences:[["然后列子自以为未始学而归。三年不出，为其妻",{text:"爨",glossary:"cuan_chui"},"，",{text:"食豕如食人",glossary:"shi_shi_ren"},"，于事无与亲。"],["雕琢",{text:"复朴",glossary:"fu_pu"},"，",{text:"块然",glossary:"kuai_ran"},{text:"独以其形立",glossary:"du_xing_li"},"。"],[{text:"纷而封哉",glossary:"fen_feng_zai"},"，",{text:"一以是终",glossary:"yi_shi_zhong"},"。"]]}],b=[{id:"shen_wu",term:"神巫",pinyin:"shén wū",meaning:"神异的巫师（能预知吉凶的占卜者）。神：神异；巫：巫师，以占卜·预言为业。神巫：神异的巫师——季咸能知人死生存亡，代表以「知」（外在知识·预测能力）自居的世俗智慧。"},{id:"ji_xian",term:"季咸",pinyin:"jì xián",meaning:"人名，郑国的神巫。季咸：读 jì xián，能预知人的死生存亡祸福寿夭——代表以外在「相术」（观察形貌）把握他人命运的世俗智慧，最终被壶子的道所击败。"},{id:"qi_yi",term:"期以",pinyin:"qī yǐ",meaning:"以……为期限（精确预测到）。期：期限、预期；以：以。期以岁月旬日：精确到年·月·旬·日——极言季咸预测的精准，衬托其「神」。"},{id:"qi_tao",term:"弃",pinyin:"qì",meaning:"（弃置原路）逃开、躲避。弃而走：丢下（原来的路）逃走——郑人因惧怕季咸知其命运而逃避，衬托季咸之「神」。"},{id:"lie_zi",term:"列子",pinyin:"liè zǐ",meaning:"人名，道家人物，壶子的弟子。列子：读 liè zǐ，此处作为求道者，因见季咸而心醉，经壶子四示的教导，最终「自以为未始学而归」——从执着于「知」到回归朴真的转化历程。"},{id:"hu_zi",term:"壶子",pinyin:"hú zǐ",meaning:"人名，列子之师，得道者。壶子：读 hú zǐ，以四种不同的「示」（地文·天壤·太冲莫胜·未始出吾宗）应对季咸的相术，令季咸无从把握，最终逃走——代表道的深不可测与无形无迹。"},{id:"you_zhi_zhe",term:"有至焉者矣",pinyin:"yǒu zhì yān zhě yǐ",meaning:"还有比（夫子之道）更高的存在啊。有至焉者：有更高（至极）的存在；矣：语气词。则又有至焉者矣：原来还有比夫子之道更高的——列子以季咸的「神」为更高，误以外在预测能力为道，壶子随即纠正。"},{id:"ji_qi_wen",term:"既其文",pinyin:"jì qí wén",meaning:"已经（传授了）道的文（外在形式）。既：已经；文：文采·外在形式·表面。吾与汝既其文：我已经传授给你道的外在形式——壶子承认已教列子道的表面，但尚未传授道的本质。"},{id:"wei_ji_shi",term:"未既其实",pinyin:"wèi jì qí shí",meaning:"尚未（传授）道的实（内在本质）。未既：尚未完成；其实：道的内在本质。既其文·未既其实：已授其文·未授其实——点出列子的问题：只得道的外在形式，未得道的内在本质，故被季咸所惑。"},{id:"er_gu_de_dao",term:"而固得道与",pinyin:"ér gù dé dào yú",meaning:"你真的得道了吗？而：你；固：真的、果真；得道：得到道；与：疑问语气词。而固得道与：你果真得道了吗？——壶子以反问质疑列子，点出其尚未真正得道。"},{id:"xi_luan",term:"而又奚卵焉",pinyin:"ér yòu xī luǎn yān",meaning:"又怎么能孵出蛋来呢！奚：怎么；卵：孵蛋（此处为动词）；焉：语气词。众雌而无雄，而又奚卵焉：全是雌的而没有雄的，又怎么能孵出蛋来——以「众雌无雄」喻列子只得道之文（外在）而无道之实（内在），有形无神，无法真正生发。"},{id:"shi_kang",term:"世亢",pinyin:"shì kàng",meaning:"与世俗相抗衡（以道炫耀于世）。世：世俗；亢：抗衡、对抗，读 kàng。而以道与世亢：你以道与世俗相抗衡——列子以道自居，在世人面前炫耀，故被季咸所相（观察）。"},{id:"de_xiang_ru",term:"得而相汝",pinyin:"dé ér xiàng rǔ",meaning:"能够观相你（把握你的状态）。得：能够；相：观相、相面，读 xiàng；汝：你。夫故使人得而相汝：所以使人能够观相你——列子以道炫耀，形于外，故被季咸所相。若真得道，深不可测，季咸无从相之。"},{id:"chang_shi_yu_lai",term:"尝试与来",pinyin:"cháng shì yǔ lái",meaning:"试着带他来（让我试试）。尝试：试着；与：带领；来：前来。尝试与来：试着带他来——壶子主动邀请季咸前来，以「示之」应对其相术。"},{id:"yi_yu_shi_zhi",term:"以予示之",pinyin:"yǐ yǔ shì zhī",meaning:"把我（的状态）展示给他看。以：把；予：我；示之：展示给他看。以予示之：让我来展示给他看——壶子以自身的道境应对季咸，四次展示不同的「机」。"},{id:"bu_xun_shu",term:"不以旬数矣",pinyin:"bù yǐ xún shǔ yǐ",meaning:"活不过十天了。不以旬数：不以旬（十天）来计算（剩余时日）；矣：语气词。不以旬数矣：活不过十天——季咸第一次相壶子，断其必死，因壶子示以「地文」（死寂之象）。"},{id:"jian_guai",term:"吾见怪焉",pinyin:"wú jiàn guài yān",meaning:"我看到了异常（死兆）。见怪：看到异常·怪异之象；焉：语气词。吾见怪焉：我看到了死兆——季咸所见的「怪」是壶子示以地文的死寂之象。"},{id:"jian_shi_hui",term:"见湿灰焉",pinyin:"jiàn shī huī yān",meaning:"看到了湿灰（死灰·生机熄灭之象）。湿灰：湿润的灰烬，喻生机熄灭、死气沉沉。见湿灰焉：看到了湿灰之象——湿灰是死灰（熄灭的火）加湿，彻底熄灭，喻生机全无。吾见怪焉·见湿灰焉：两个死兆并举，描绘季咸所见壶子「地文」之象——死寂·熄灭，无生机。"},{id:"qi_ti_zhan_jin",term:"泣涕沾襟",pinyin:"qì tì zhān jīn",meaning:"哭泣流泪沾湿了衣襟。泣：哭泣；涕：眼泪；沾：沾湿；襟：衣襟。泣涕沾襟：泪水沾湿衣襟——列子信以为真，悲痛欲绝，衬托其尚未真正理解壶子之道。"},{id:"xiang_shi_zhi",term:"乡吾示之",pinyin:"xiāng wú shì zhī",meaning:"刚才我展示给他的（是……）。乡：刚才，通「向」；吾：我；示之：展示给他。乡吾示之以……：刚才我展示给他的是……——四次「乡吾示之」，分别引出四种「机」的说明。"},{id:"di_wen",term:"地文",pinyin:"dì wén",meaning:"大地的纹理（静止·死寂之象）。地文：大地的纹理，喻静止·沉寂·生机潜藏未发。乡吾示之以地文：刚才我展示给他的是地文——第一示：静止死寂，生机潜藏，季咸见「湿灰」之象，断其必死。"},{id:"meng_hu",term:"萌乎",pinyin:"méng hū",meaning:"萌动的状态（微微萌动却未发）。萌：萌动、微微生发；乎：……的样子。萌乎不震不正：微微萌动却不震动不端正——生机潜藏，似有若无。"},{id:"bu_zhen_bu_zheng",term:"不震不正",pinyin:"bù zhèn bù zhèng",meaning:"不震动不端正（生机未发·静止潜藏）。不震：不震动；不正：不端正（不显现）。萌乎不震不正：微微萌动却不震动不显现——描绘地文之象：生机潜藏，外表死寂。"},{id:"dai_gai",term:"殆",pinyin:"dài",meaning:"大概、恐怕（副词，表推测）。殆：大概、恐怕。是殆见吾……机也：这大概是（季咸）看到了我的……之机——壶子以「殆」表推测，点出季咸所见只是壶子刻意展示的某一「机」，并非壶子的全貌。"},{id:"du_de_ji",term:"杜德机也",pinyin:"dù dé jī yě",meaning:"闭塞德性之机（生机封闭·不外露）。杜：堵塞、封闭；德机：德性的生机、生命的机枢。杜德机：封闭德性之机——第一示的本质：壶子刻意封闭生机，呈现死寂之象，令季咸误以为必死。"},{id:"chang_you_yu_lai",term:"尝又与来",pinyin:"cháng yòu yǔ lái",meaning:"再试着带他来（再来一次）。尝：试着；又：再；与来：带来。尝又与来：再带他来试试——三次重复，推动四示的叙事节奏。"},{id:"xing_yi",term:"幸矣",pinyin:"xìng yǐ",meaning:"幸运啊（庆幸）。幸：幸运；矣：语气词。幸矣，子之先生遇我也：幸运啊，你的先生遇到了我——季咸第二次相壶子，见生机勃发，断其有救，与第一次「必死」形成鲜明对比。"},{id:"you_chou",term:"有瘳矣",pinyin:"yǒu chōu yǐ",meaning:"有好转了（病情好转）。瘳：病愈、好转，读 chōu；矣：语气词。有瘳矣：有好转了——季咸见壶子「天壤」之象，以为其病情好转，实则壶子示以生机勃发之象。"},{id:"quan_ran",term:"全然",pinyin:"quán rán",meaning:"完全·充盈的样子（生机充盈）。全：完全、充盈；然：……的样子。全然有生矣：充盈地有生机了——季咸见天壤之象，感受到生机充盈。"},{id:"du_quan",term:"杜权矣",pinyin:"dù quán yǐ",meaning:"看到了（生机的）权衡枢机（生机勃发之机）。杜权：此处「杜」通「睹」，看到；权：权衡·枢机。吾见其杜权矣：我看到了他的生机枢机——季咸所见的是壶子示以天壤的生机勃发之象。"},{id:"tian_rang",term:"天壤",pinyin:"tiān rǎng",meaning:"天地之间（生机勃发之象）。天壤：天与地之间，喻生机充盈·万物生发。乡吾示之以天壤：刚才我展示给他的是天壤——第二示：生机勃发，与地文（死寂）相对。"},{id:"ming_shi_bu_ru",term:"名实不入",pinyin:"míng shí bù rù",meaning:"名称与实体都不进入（超越名实的执着）。名：名称；实：实体；不入：不进入（不被名实所束缚）。名实不入：超越名实——天壤之示的特点：超越名实，生机自然流露。"},{id:"ji_fa_zhong",term:"机发于踵",pinyin:"jī fā yú zhǒng",meaning:"生机从脚跟发出（生机从根本处自然涌现）。机：生机·机枢；发：发出；踵：脚跟，读 zhǒng，喻根本·底部。机发于踵：生机从脚跟（根本）自然涌现——天壤之示的生机是从根本处自然流露，非刻意为之。"},{id:"shan_zhe_ji",term:"善者机也",pinyin:"shàn zhě jī yě",meaning:"生机勃发（善好）的机枢。善者机：善好·生机勃发的机枢。殆见吾善者机也：大概是（季咸）看到了我生机勃发的机枢——第二示的本质：壶子展示生机充盈之象，令季咸误以为好转。"},{id:"bu_qi_xin",term:"不齐",pinyin:"bù qí",meaning:"（心神）不齐整（状态不稳定·无从把握）。不齐：不整齐·不稳定。子之先生不齐：你的先生（状态）不齐整——季咸第三次相壶子，无从判断，因壶子示以太冲莫胜（不偏不倚·无可把握）。"},{id:"wu_de_xiang",term:"无得而相焉",pinyin:"wú dé ér xiàng yān",meaning:"无法观相（无从把握）。无得：无法；相：观相，读 xiàng；焉：语气词。吾无得而相焉：我无法观相他——季咸第三次失手，无从判断，是壶子四示中的关键转折。"},{id:"shi_zhai",term:"试齐",pinyin:"shì zhāi",meaning:"试着（让他）斋戒（使心神齐整）。试：试着；齐：通「斋」，斋戒·使心神齐整，读 zhāi。试齐，且复相之：试着让他斋戒，再来观相——季咸以为是壶子状态不稳，要求其斋戒，实则是壶子的太冲莫胜令其无从把握。"},{id:"fu_xiang_zhi",term:"复相之",pinyin:"fù xiàng zhī",meaning:"再来观相他。复：再；相之：观相他，读 xiàng。且复相之：再来观相他——季咸仍试图把握壶子，为第四示的彻底逃走埋下伏笔。"},{id:"tai_chong_mo_sheng",term:"太冲莫胜",pinyin:"tài chōng mò shèng",meaning:"极度冲和·无所偏胜（道的中和状态）。太冲：极度冲和·浑然中和；莫胜：无所偏胜·无一方占优。太冲莫胜：极度冲和·无所偏胜——第三示：壶子呈现道的中和状态，不偏不倚，无可把握，令季咸无从相之。"},{id:"heng_qi_ji",term:"衡气机也",pinyin:"héng qì jī yě",meaning:"气机平衡（不偏不倚）的机枢。衡：平衡·均衡；气机：气的机枢·运行状态。殆见吾衡气机也：大概是看到了我气机平衡的机枢——第三示的本质：气机平衡，无可偏倚，故季咸无从把握。"},{id:"ni_huan_yuan",term:"鲵桓之审为渊",pinyin:"ní huán zhī shěn wéi yuān",meaning:"鲵鱼盘旋之处成为深渊。鲵：大鱼（鲵鱼），读 ní；桓：盘旋；审：确实·之处；为渊：成为深渊。鲵桓之审为渊：鲵鱼盘旋之处形成深渊——以动水成渊喻太冲莫胜的气机。"},{id:"zhi_shui_yuan",term:"止水之审为渊",pinyin:"zhǐ shuǐ zhī shěn wéi yuān",meaning:"止水（静止之水）之处成为深渊。止水：静止的水；之审为渊：之处成为深渊。止水之审为渊：静止之水形成深渊——以静水成渊喻太冲莫胜的静止之机。"},{id:"liu_shui_yuan",term:"流水之审为渊",pinyin:"liú shuǐ zhī shěn wéi yuān",meaning:"流水之处成为深渊。流水：流动的水；之审为渊：之处成为深渊。流水之审为渊：流水形成深渊——以流水成渊喻太冲莫胜的流动之机。鲵桓·止水·流水：三种水皆可成渊——喻壶子的太冲莫胜如渊，动静皆深，无从把握。"},{id:"yuan_jiu_ming",term:"渊有九名",pinyin:"yuān yǒu jiǔ míng",meaning:"渊有九种名称（深渊的多种形态）。渊有九名：深渊有九种名称——此处三焉（鲵桓·止水·流水），喻壶子的道如渊之深，形态多样，无从穷尽。"},{id:"li_wei_ding",term:"立未定",pinyin:"lì wèi dìng",meaning:"（季咸）站立还未稳定（尚未站定）。立：站立；未定：未稳定。立未定，自失而走：站立还未稳，便自失而逃——第四示：壶子示以「未始出吾宗」，季咸甫一接触便彻底崩溃逃走。"},{id:"zi_shi_zou",term:"自失而走",pinyin:"zì shī ér zǒu",meaning:"自我迷失（惊慌失措）而逃走。自失：自我迷失·惊慌失措；走：逃走。自失而走：惊慌失措地逃走——季咸面对壶子「未始出吾宗」的道之本源，彻底无从把握，惊慌逃走。"},{id:"zhui_bu_ji",term:"追之不及",pinyin:"zhuī zhī bù jí",meaning:"追赶他却追不上。追之：追赶他；不及：追不上。列子追之不及：列子追赶季咸却追不上——季咸逃得彻底，连追都追不上。"},{id:"mie_shi_zong",term:"灭·失",pinyin:"miè · shī",meaning:"消失·踪迹全无。灭：消灭·消失；失：失踪·踪迹全无。已灭矣，已失矣：已经消失了，已经踪迹全无了——两字叠用，强调季咸逃遁之彻底。"},{id:"wei_shi_chu_zong",term:"未始出吾宗",pinyin:"wèi shǐ chū wú zōng",meaning:"从未离开过我的本源（道之根本）。未始：从未；出：离开；吾宗：我的本源·根本（道）。乡吾示之以未始出吾宗：刚才我展示给他的是从未离开过我的本源——第四示：壶子呈现道的本源，深不可测，无形无迹，季咸完全无从把握。"},{id:"xu_wei_yi",term:"虚而委蛇",pinyin:"xū ér wēi yí",meaning:"虚空而随顺（如蛇般蜿蜒随形）。虚：虚空·无执；委蛇：随顺·蜿蜒随形，读 wēi yí。吾与之虚而委蛇：我以虚空随顺的状态应对他——壶子以虚无随顺之态，令季咸无从把握。"},{id:"yin_di_mi",term:"因以为弟靡",pinyin:"yīn yǐ wéi dì mí",meaning:"于是（在他看来）如同随风倒伏的草（无固定形态）。因：于是；弟靡：随风倒伏的草，读 dì mí，喻无固定形态·随顺无迹。因以为弟靡：于是（在季咸眼中）如同随风倒伏的草——壶子无固定形态，令季咸无从把握。"},{id:"yin_bo_liu",term:"因以为波流",pinyin:"yīn yǐ wéi bō liú",meaning:"于是（在他看来）如同波浪流水（无固定形态）。波流：波浪·流水，喻流动无迹·无固定形态。因以为波流：于是（在季咸眼中）如同波浪流水——弟靡·波流：两个意象并举，草随风·水随势，皆无固定形态，喻壶子的道深不可测·无从把握，故季咸逃也。"},{id:"cuan_chui",term:"爨",pinyin:"cuàn",meaning:"烧火做饭。爨：读 cuàn，烧火·炊事。为其妻爨：替妻子烧火做饭——列子回归后，甘愿做最卑微的家务，彻底放下「道」的执着与自矜。"},{id:"shi_shi_ren",term:"食豕如食人",pinyin:"sì shǐ rú sì rén",meaning:"喂猪如同喂人（一视同仁·无分别心）。食：喂食，读 sì；豕：猪，读 shǐ；如食人：如同喂人。食豕如食人：喂猪如同喂人——超越贵贱分别，对猪与人一视同仁，是「无容私焉」的具体体现。"},{id:"fu_pu",term:"复朴",pinyin:"fù pǔ",meaning:"回归朴素（本真）。复：回归；朴：朴素·本真。雕琢复朴：（放下）雕琢（的执着），回归朴素本真——「雕琢」喻刻意修饰·人为造作，「复朴」是回归道的本真状态。"},{id:"kuai_ran",term:"块然",pinyin:"kuài rán",meaning:"浑然独立的样子（如土块般朴实独立）。块：土块，喻朴实无华；然：……的样子。块然：浑然独立·朴实无华的样子——回归本真后的状态。"},{id:"du_xing_li",term:"独以其形立",pinyin:"dú yǐ qí xíng lì",meaning:"只以自身的形体独立存在。独：只；以其形：以自身的形体；立：独立存在。块然独以其形立：浑然独立，只以自身形体存在——超越一切外在执着，回归形体本身的自然存在。"},{id:"fen_feng_zai",term:"纷而封哉",pinyin:"fēn ér fēng zāi",meaning:"纷繁（万物）而各自封存（保守本真）啊。纷：纷繁·众多；封：封存·保守（各守本真）；哉：语气词，表感叹。纷而封哉：纷繁万物各自保守本真啊——万物纷繁，各守其真，无需刻意。"},{id:"yi_shi_zhong",term:"一以是终",pinyin:"yī yǐ shì zhōng",meaning:"始终如一地以此（朴真）终其一生。一：始终如一；以是：以此（朴真之道）；终：终其一生。一以是终：始终如一地以朴真终其一生——列子最终的归宿：不出·不炫·复朴·块然，一以是终。"}],z=[{id:"jing_s1",label:"无为名尸……无为知主",sentences:[[{text:"无为名尸",glossary:"wu_ming_shi"},"，",{text:"无为谋府",glossary:"wu_mou_fu"},"，",{text:"无为事任",glossary:"wu_shi_ren"},"，",{text:"无为知主",glossary:"wu_zhi_zhu"},"。"]]},{id:"jing_s2",label:"体尽无穷……亦虚而已",sentences:[[{text:"体尽无穷",glossary:"ti_jin_wuqiong"},"，而",{text:"游无朕",glossary:"you_wu_zhen"},"。"],[{text:"尽",glossary:"jin_fahui"},"其所",{text:"受",glossary:"shou_tian"},"乎天而",{text:"无见得",glossary:"wu_jian_de"},"，",{text:"亦虚而已",glossary:"yi_xu_eryi"},"！"]]},{id:"jing_s3",label:"至人之用心若镜……故能胜物而不伤",sentences:[["至人之",{text:"用心若镜",glossary:"yong_xin_jing"},"，"],[{text:"不将不逆",glossary:"bu_jiang_ni"},"，",{text:"应而不藏",glossary:"ying_bu_cang"},"，"],["故能",{text:"胜物而不伤",glossary:"sheng_wu_bu_shang"},"。"]]}],c=[{id:"wu_ming_shi",term:"无为名尸",pinyin:"wú wéi míng shī",meaning:"不做名声的主宰（不以名声自居）。名：名声·名誉；尸：主宰·占据（古代「尸」有主持·占据之意）。无为名尸：不以名声为主宰——不执着于名声，不让名声占据自身。"},{id:"wu_mou_fu",term:"无为谋府",pinyin:"wú wéi móu fǔ",meaning:"不做谋略的府库（不以谋略自居）。谋：谋略·计谋；府：府库·储藏之所。无为谋府：不以谋略为府库——不执着于谋略，不让谋略占据自身。"},{id:"wu_shi_ren",term:"无为事任",pinyin:"wú wéi shì rèn",meaning:"不做事务的承担者（不以事务自任）。事：事务·职责；任：承担·担任。无为事任：不以事务为担当——不执着于事务，不让事务占据自身。"},{id:"wu_zhi_zhu",term:"无为知主",pinyin:"wú wéi zhī zhǔ",meaning:"不做知识的主人（不以知识自居）。知：知识·智慧；主：主人·主宰。无为知主：不以知识为主宰——不执着于知识，不让知识占据自身。无为名尸·无为谋府·无为事任·无为知主：四「无为」并举，分别对应名·谋·事·知四种执着——不以名声·谋略·事务·知识自居，超越一切「有为」的执着，是至人用心的前提。"},{id:"ti_jin_wuqiong",term:"体尽无穷",pinyin:"tǐ jìn wú qióng",meaning:"以身体验（道的）无穷无尽。体：以身体验·体悟；尽：穷尽·完全；无穷：无穷无尽（道）。体尽无穷：以身完全体悟道的无穷无尽——超越一切有限，与道的无穷合一。"},{id:"you_wu_zhen",term:"游无朕",pinyin:"yóu wú zhèn",meaning:"遨游于无迹可寻之境。游：遨游；无朕：没有迹象·无形无迹，读 zhèn（朕：迹象·征兆，古义）。游无朕：遨游于无形无迹之境——超越一切可见可知的迹象，与道的无形合一。体尽无穷·游无朕：一「体」一「游」，体悟无穷·遨游无迹——至人的存在状态：内体道之无穷，外游道之无迹。"},{id:"jin_fahui",term:"尽",pinyin:"jìn",meaning:"充分发挥·完全实现。尽其所受乎天：充分发挥（实现）天所赋予的（本性）——不多不少，完全顺应天赋本性。"},{id:"shou_tian",term:"受",pinyin:"shòu",meaning:"承受·接受（天所赋予的）。受乎天：承受于天·天所赋予的。尽其所受乎天：充分发挥天所赋予的（本性）——顺应天赋，不增不减。"},{id:"wu_jian_de",term:"无见得",pinyin:"wú xiàn dé",meaning:"不显现（执着于）所得（不以所得自居）。无：不；见：显现·表现，读 xiàn；得：所得·获得。无见得：不显现执着于所得——顺应天赋而不以所得自矜，无执无藏。尽其所受乎天而无见得：充分发挥天赋本性却不以所得自居——「尽」是完全顺应，「无见得」是不执着于结果，两者合一，方是「亦虚而已」。"},{id:"yi_xu_eryi",term:"亦虚而已",pinyin:"yì xū ér yǐ",meaning:"也不过是虚（空）罢了。亦：也；虚：虚空·无执；而已：罢了·仅此。亦虚而已：也不过是虚空罢了——至人体尽无穷·游无朕·尽天赋·无见得，归根结底不过是「虚」——虚是道的本质，也是至人用心的根本。"},{id:"yong_xin_jing",term:"用心若镜",pinyin:"yòng xīn ruò jìng",meaning:"用心如同镜子（如实映照·无执无藏）。用心：运用心神；若镜：如同镜子。用心若镜：心如镜子——镜子的特性：来者照之，去者不留，如实映照，无好无恶，无执无藏。至人之用心若镜：至人的用心如同镜子——是本节的核心意象，统摄「不将不逆·应而不藏」。"},{id:"bu_jiang_ni",term:"不将不逆",pinyin:"bù jiāng bù nì",meaning:"不送往不迎来（不主动追送·不主动迎接）。将：送往·追送；逆：迎来·迎接，读 nì。不将不逆：不送往不迎来——镜子不追送离去之物，不迎接将来之物，如实映照当下，无执于过去与未来。"},{id:"ying_bu_cang",term:"应而不藏",pinyin:"yìng ér bù cáng",meaning:"应物而不留藏（如实回应而不执留）。应：回应·应对；不藏：不留藏·不执留。应而不藏：回应而不留藏——镜子如实映照来物，物去则不留，无执无藏。不将不逆·应而不藏：三句描绘镜心的三个维度——不送（无执于去）·不迎（无执于来）·应而不藏（无执于当下）——完整描绘至人用心的无执状态。"},{id:"sheng_wu_bu_shang",term:"胜物而不伤",pinyin:"shèng wù ér bù shāng",meaning:"超越（应对）万物而不受伤害。胜：超越·胜任·应对；物：万物·外物；不伤：不受伤害。故能胜物而不伤：所以能够应对万物而不受伤害——因用心若镜（不将不逆·应而不藏），故能与万物相应而不被万物所伤，超越一切外物的干扰。"}],w=[{id:"hun_s1",label:"南海之帝为儵……浑沌待之甚善",sentences:[["南海之帝为",{text:"儵",glossary:"shu_di"},"，北海之帝为",{text:"忽",glossary:"hu_di"},"，中央之帝为",{text:"浑沌",glossary:"hun_dun"},"。"],[{text:"儵",glossary:"shu_di"},"与",{text:"忽",glossary:"hu_di"},"时相与遇于浑沌之地，浑沌待之甚善。"]]},{id:"hun_s2",label:"儵与忽谋报浑沌之德……尝试凿之",sentences:[[{text:"儵",glossary:"shu_di"},"与",{text:"忽",glossary:"hu_di"},{text:"谋报",glossary:"mou_bao"},"浑沌之德，曰：「人皆有",{text:"七窍",glossary:"qi_qiao"},"以",{text:"视听食息",glossary:"shi_ting_shi_xi"},"，",{text:"此",glossary:"ci_hundun"},"独无有，尝试",{text:"凿",glossary:"zao_qiao"},"之。」"]]},{id:"hun_s3",label:"日凿一窍……七日而浑沌死",sentences:[["日",{text:"凿",glossary:"zao_qiao"},"一窍，七日而浑沌死。"]]}],j=[{id:"shu_di",term:"儵",pinyin:"shū",meaning:"南海之帝，「迅疾」之义。儵：读 shū，迅疾·快速。儵与忽：南海·北海之帝，以「儵」「忽」命名，合为「倏忽」——迅疾短暂·转瞬即逝，象征有为·有形·有分别的时间性存在，与浑沌的永恒混一形成对比。"},{id:"hu_di",term:"忽",pinyin:"hū",meaning:"北海之帝，「忽然」之义。忽：读 hū，忽然·转瞬。儵忽合称：倏忽——转瞬即逝，象征有为·有分别·有意图的世俗之力，正是这种「好意」的有为之力，凿死了浑沌。"},{id:"hun_dun",term:"浑沌",pinyin:"hún dùn",meaning:"中央之帝，混沌未分之道的象征。浑沌：读 hún dùn，混沌·未分化的整体状态。浑沌：庄子《应帝王》终篇的核心意象——象征道的本然状态：无形·无分别·无七窍，浑然一体。浑沌待儵忽甚善，却被儵忽以「好意」凿七窍而死——以寓言点出：以有为（人为分别）干预无为（道的本然），必致道之死亡。"},{id:"mou_bao",term:"谋报",pinyin:"móu bào",meaning:"商议报答（浑沌的恩德）。谋：商议·谋划；报：报答。谋报浑沌之德：商议如何报答浑沌的恩德——儵与忽出于「好意」，以人的标准（七窍）报答浑沌，正是有为干预无为的起点。"},{id:"qi_qiao",term:"七窍",pinyin:"qī qiào",meaning:"人面部的七个孔窍（眼二·耳二·鼻二·口一）。七窍：两眼·两耳·两鼻孔·一口，共七窍——人感知外界的器官，象征有形·有分别·有感知的世俗存在状态。人皆有七窍：人人都有七窍——儵忽以「人皆有」为标准，将人的分别强加于浑沌，是「以己出经式义度」的极端体现。"},{id:"shi_ting_shi_xi",term:"视听食息",pinyin:"shì tīng shí xī",meaning:"看·听·吃·呼吸（人的基本感知与生存活动）。视：看；听：听；食：吃；息：呼吸。视听食息：人的四种基本感知与生存活动——儵忽以「视听食息」为人的必要功能，认为浑沌无七窍则无法视听食息，出于好意为其凿窍，实则以人的标准强加于道。"},{id:"ci_hundun",term:"此",pinyin:"cǐ",meaning:"这（指浑沌）。此独无有：这（浑沌）偏偏没有——以「此独无有」点出浑沌与人的根本差异：浑沌无七窍，正是其混沌本然·道之完整的体现，非缺陷。"},{id:"zao_qiao",term:"凿",pinyin:"záo",meaning:"凿开·挖凿（孔窍）。凿：读 záo，凿开·挖凿。尝试凿之·日凿一窍：试着凿开·每天凿一窍——「凿」是全篇最关键的动词，象征以有为（人为分别·刻意干预）破坏道的本然完整。七日而浑沌死：七窍凿完，浑沌死——每凿一窍，道的完整性减损一分，七窍凿毕，浑沌（道）彻底死亡。"}];return(D,n)=>{const q=g("DaoReadingPrelude"),a=g("DaoTextReading"),s=g("DaoKeywordCards"),r=g("DaoLineGuide");return k(),P("div",null,[n[0]||(n[0]=d("",3)),t(q,{title:"从在宥天下到浑沌之死，内篇以「应」作结",summary:"《应帝王》是内篇七篇的收束之篇。庄子从「在宥天下」立论，破有为之治（藏仁要人、经式义度），立无为之治（游心于淡、顺物自然），再以壶子四示、至人若镜、浑沌之死层层证明：真正的治，不是改变天下，而是像镜子一样回应天下。",points:[{label:"先看",text:"顺着破有为（1-2）、立无为（3-4）、证无为（5-7）三个部分走一遍。"},{label:"再问",text:"壶子四示为什么让神巫季咸「自失而走」？"},{label:"最后",text:"儵与忽出于善意凿七窍，为什么反而杀死了浑沌？"}],hint:"这是内篇的出口。读完后可以回头把逍遥游到应帝王七篇连成一条完整的弧线。"}),n[1]||(n[1]=i("h2",{id:"一、啮缺四问·有虞氏不及泰氏",tabindex:"-1"},[e("一、啮缺四问·有虞氏不及泰氏 "),i("a",{class:"header-anchor",href:"#一、啮缺四问·有虞氏不及泰氏","aria-label":'Permalink to "一、啮缺四问·有虞氏不及泰氏"'},"​")],-1)),n[2]||(n[2]=i("h3",{id:"原文",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),t(a,{sections:y,glossary:l,"default-mode":"classic","aria-label":"应帝王·啮缺四问 原文"}),n[3]||(n[3]=i("h3",{id:"生僻字词",tabindex:"-1"},[e("生僻字词 "),i("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),t(s,{items:[{term:"啮缺",pinyin:["niè","quē"],meaning:"人名，虚构。《齐物论》中亦出现。"},{term:"王倪",pinyin:["wáng","ní"],meaning:"人名，虚构。啮缺之师。"},{term:"蒲衣子",pinyin:["pú","yī","zǐ"],meaning:"人名，虚构。王倪之师。"},{term:"跃而大喜",pinyin:["yuè","ér","dà","xǐ"],meaning:"跃：跳跃。欣喜雀跃。"},{term:"有虞氏",pinyin:["yǒu","yú","shì"],meaning:"即舜，儒家圣王之一。"},{term:"泰氏",pinyin:["tài","shì"],meaning:"传说中比舜更古远的圣王，近乎神话。"},{term:"藏仁以要人",pinyin:["cáng","rén","yǐ","yāo","rén"],meaning:"藏仁义以笼络人心。要：求取、笼络。"},{term:"卧徐徐",pinyin:["wò","xú","xú"],meaning:"睡得从容舒缓。"},{term:"觉于于",pinyin:["jué","yú","yú"],meaning:"觉：醒来；于于：自得自在的样子。"}]}),n[4]||(n[4]=i("h3",{id:"核心句引读",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),t(r,{title:"四问而四不知，啮缺跃而大喜",subtitle:"「不知道」，不是失败，而是一种境界。",lines:[{text:"啮缺问于王倪，四问而四不知。啮缺因跃而大喜。",tone:"反常识",guide:"《应帝王》开篇，是一个反常识的场景：学生问了四个问题，老师四次回答「不知道」——学生不是失望，而是跃而大喜。这个「喜」，是全篇的第一个关键信号：「不知道」，不是失败，而是一种境界。王倪的「四不知」，与《齐物论》中同一场对话呼应——那里王倪说的是：我怎么知道我所谓的「知」不是「不知」？知与不知的边界，本身就是模糊的。啮缺的喜，是因为他懂了：一个真正得道的人，不执着于「知道」——四不知，正是王倪得道的证明。"},{text:"有虞氏其犹藏仁以要人，亦得人矣，而未始出于非人。",tone:"有为",guide:"蒲衣子用两位圣王做对比，层层递进：有虞氏（舜）藏仁义以笼络人心，确实得到了人心，但「未始出于非人」——始终没有超出「人为」的范畴。舜的治理，是有意识的、有目的的——用仁义作为工具，来达到治世的目的。这不是坏事，但这是有为——仁义是他的手段，人心是他的目标，整个过程，都在「人为」的框架里。"},{text:"泰氏其卧徐徐，其觉于于。一以己为马，一以己为牛。其知情信，其德甚真，而未始入于非人。",tone:"浑然",guide:"泰氏——比舜更古远，近乎神话的存在：卧徐徐（睡得从容，没有忧虑），觉于于（醒来自在，没有执着），一以己为马，一以己为牛（别人叫他马，他就是马；叫他牛，他就是牛——完全没有自我的执着，随物而化）。「未始入于非人」——泰氏从未进入「非人为」的范畴——他不是「人为的」，而是浑然天成，连「人为」与「非人为」的区别，在他那里都消失了。舜是「未始出于非人」——在人为里，但努力超越；泰氏是「未始入于非人」——根本没有「人为」与否的分别。这是两个完全不同的层次。"}]}),n[5]||(n[5]=i("h2",{id:"二、肩吾见狂接舆·欺德",tabindex:"-1"},[e("二、肩吾见狂接舆·欺德 "),i("a",{class:"header-anchor",href:"#二、肩吾见狂接舆·欺德","aria-label":'Permalink to "二、肩吾见狂接舆·欺德"'},"​")],-1)),n[6]||(n[6]=i("h3",{id:"原文-1",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-1","aria-label":'Permalink to "原文"'},"​")],-1)),t(a,{sections:o,glossary:_,"default-mode":"classic","aria-label":"应帝王·肩吾见狂接舆 原文"}),n[7]||(n[7]=i("h3",{id:"生僻字词-1",tabindex:"-1"},[e("生僻字词 "),i("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),t(s,{items:[{term:"肩吾",pinyin:["jiān","wú"],meaning:"人名，虚构。《逍遥游》《大宗师》中亦出现。"},{term:"狂接舆",pinyin:["kuáng","jiē","yú"],meaning:"楚国隐士，佯狂避世。《论语》中亦有记载。"},{term:"日中始",pinyin:["rì","zhōng","shǐ"],meaning:"人名，虚构。肩吾的老师。"},{term:"君人者",pinyin:["jūn","rén","zhě"],meaning:"统治人民的人，君主。"},{term:"经式义度",pinyin:["jīng","shì","yì","dù"],meaning:"经：纲纪；式：法式；义：道义；度：制度。一套完整的治理规范。"},{term:"欺德",pinyin:["qī","dé"],meaning:"以人为的规范欺骗（遮蔽）了本真之德。"},{term:"涉海凿河",pinyin:["shè","hǎi","záo","hé"],meaning:"徒步横渡大海、用手凿开大河。喻不可能之事。"},{term:"使蚊负山",pinyin:["shǐ","wén","fù","shān"],meaning:"让蚊子背负大山。喻力不能及之事。"},{term:"正而后行",pinyin:["zhèng","ér","hòu","xíng"],meaning:"先端正自身，然后自然而行。"},{term:"矰弋",pinyin:["zēng","yì"],meaning:"矰：带绳的短箭；弋：用绳系箭射鸟。射鸟的箭。"},{term:"鼷鼠",pinyin:["xī","shǔ"],meaning:"极小的鼠，田鼠。"},{term:"神丘",pinyin:["shén","qiū"],meaning:"社神之丘，祭祀之地，不可随意挖掘。"},{term:"熏凿",pinyin:["xūn","záo"],meaning:"熏：烟熏；凿：挖掘。驱除鼠患的手段。"}]}),n[8]||(n[8]=i("h3",{id:"核心句引读-1",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),t(r,{title:"以己出经式义度，是欺德",subtitle:"用外在的规范来强加于人，本身就是对人本真之德的遮蔽。",lines:[{text:"君人者以己出经式义度，人孰敢不听而化诸！",tone:"有为",guide:"日中始告诉肩吾的，是一套典型的儒家治理逻辑：君主用自己制定的纲纪、法式、道义、制度来治理——人们谁敢不听从、不被教化？这听起来很有道理——君主有权威，有规范，有道义，天下自然归顺。但狂接舆听完，只说了三个字：是欺德也。"},{text:"是欺德也。其于治天下也，犹涉海凿河而使蚊负山也。",tone:"欺德",guide:"不是说君主的仁义是假的，而是说：用外在的规范来强加于人，本身就是对人本真之德的遮蔽。人的本真之德，是自然流出的——不需要被「经式义度」来规范，一旦用规范来框定，德就不再是真德，而是被规范塑造出来的「德的样子」。狂接舆用三个不可能的比喻，来描述「以己出经式义度」的荒谬：涉海（徒步横渡大海）、凿河（用手凿开大河）、使蚊负山（让蚊子背负大山）。为什么这三件事不可能？不是因为不努力，而是因为方向根本就错了——用人为的规范来改变人的本真，就像让蚊子背山，力量再大也无济于事。"},{text:"夫圣人之治也，治外夫？正而后行，确乎能其事者而已矣。",tone:"圣治",guide:"狂接舆给出了圣人之治的正面定义：圣人的治理，是从外部强加的吗？不是——正而后行（先端正自身，然后自然而行），确乎能其事者而已矣（确实能做好自己本分的事，就够了）。这两句，是《应帝王》对「治」的根本重新定义：治，不是改变别人，而是端正自己；不是强加规范，而是做好本分。当圣人端正了自身，自然而行——天下不是被「治」了，而是被感化了，被带动了——就像风吹过，草自然倒伏，不是被强迫的。"},{text:"鸟高飞以避矰弋之害，鼷鼠深穴乎神丘之下以避熏凿之患，而曾二虫之无知？",tone:"反问",guide:"狂接舆最后用两个小动物来收尾，是《应帝王》中最有趣的一个反问：鸟儿高飞，是为了躲避弓箭——这是鸟的智慧；田鼠深穴于神丘之下，是为了躲避烟熏挖掘——这是鼠的智慧。难道这两种小动物都不如（那些以己出经式义度的君主）吗？鸟和鼠，顺应自己的本性，找到最适合自己的生存方式——这是真正的智慧：顺应本性，而不是强加规范。君主以己出经式义度，连鸟高飞、鼠深穴这种顺应本性的智慧都不如——因为他们在用外在的规范，对抗人的本性。"}]}),n[9]||(n[9]=i("h2",{id:"三、天根问治·无名人·游心于淡合气于漠",tabindex:"-1"},[e("三、天根问治·无名人·游心于淡合气于漠 "),i("a",{class:"header-anchor",href:"#三、天根问治·无名人·游心于淡合气于漠","aria-label":'Permalink to "三、天根问治·无名人·游心于淡合气于漠"'},"​")],-1)),n[10]||(n[10]=i("h3",{id:"原文-2",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-2","aria-label":'Permalink to "原文"'},"​")],-1)),t(a,{sections:m,glossary:h,"default-mode":"classic","aria-label":"应帝王·天根问治 原文"}),n[11]||(n[11]=i("h3",{id:"生僻字词-2",tabindex:"-1"},[e("生僻字词 "),i("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),t(s,{items:[{term:"天根",pinyin:["tiān","gēn"],meaning:"人名，虚构。问道者。"},{term:"殷阳",pinyin:["yīn","yáng"],meaning:"地名，虚构。殷山之南。"},{term:"蓼水",pinyin:["liǎo","shuǐ"],meaning:"地名，虚构。水名。"},{term:"无名人",pinyin:["wú","míng","rén"],meaning:"人名，虚构。无名，即得道者。"},{term:"不豫",pinyin:["bù","yù"],meaning:"豫：愉快、舒畅。不令人愉快，令人扫兴。"},{term:"莽眇之鸟",pinyin:["mǎng","miǎo"],meaning:"莽眇：广远渺茫。广远渺茫之鸟，喻超脱之想象。"},{term:"六极之外",pinyin:["liù","jí"],meaning:"六极：上下四方，宇宙六个极端。"},{term:"无何有之乡",pinyin:["wú","hé","yǒu","zhī","xiāng"],meaning:"什么都没有的地方。《逍遥游》中亦出现。"},{term:"圹埌之野",pinyin:["kuàng","làng"],meaning:"圹埌：空旷无际。空旷无际的原野。"},{term:"游心于淡",pinyin:["yóu","xīn","yú","dàn"],meaning:"让心神游于淡泊之中，不执着于任何目标。"},{term:"合气于漠",pinyin:["hé","qì","yú","mò"],meaning:"让气息融合于寂漠之中，不被任何欲望牵引。"}]}),n[12]||(n[12]=i("h3",{id:"核心句引读-2",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),t(r,{title:"游心于淡，合气于漠，顺物自然而无容私焉，而天下治矣",subtitle:"不是「我治天下」，而是「天下自治」——万物各有其自然本性，只要不去干扰它。",lines:[{text:"去！汝鄙人也，何问之不豫也！",tone:"驱赶",guide:"无名人的第一反应，是驱赶——走开！你这个浅陋的人，问这种扫兴的问题！这个开场，与《大宗师》女偊说「子非其人也」如出一辙——不是拒绝，而是最深的诚实：你还没准备好问这个问题。「治天下」这个问题，本身就暴露了提问者的局限——一个还在问「如何治天下」的人，说明他还在「治」的框架里，还没有超出「有为」的预设。"},{text:"予方将与造物者为人，厌则又乘夫莽眇之鸟，以出六极之外，而游无何有之乡，以处圹埌之野。",tone:"所在",guide:"无名人描述自己正在做的事——与造物者为伴（与道同游，不在人间的框架里），乘莽眇之鸟（骑着广远渺茫的想象之鸟），出六极之外（超出宇宙的六个极端），游无何有之乡（游于什么都没有的地方），处圹埌之野（居于空旷无际的原野）。这五句，是《逍遥游》境界在《应帝王》中的直接回响——「无何有之乡」，在《逍遥游》中已经出现过。无名人说这些，不是在炫耀，而是在说：我现在所在的地方，与「治天下」这个问题，根本不在同一个维度。"},{text:"汝游心于淡，合气于漠，顺物自然而无容私焉，而天下治矣。",tone:"核心",guide:"天根再次追问，无名人才给出答案——这是《应帝王》全篇最核心的一句话，也是庄子对「无为而治」最精炼的正面表述：游心于淡（让心神游于淡泊，不执着于任何目标），合气于漠（让气息融合于寂漠，不被任何欲望牵引），顺物自然（顺应万物各自的自然本性），无容私焉（不掺入任何私意、私心、私欲）——而天下治矣。这四句，是《应帝王》的核心答案，但它的逻辑，与所有「治理学」都相反：通常的治理逻辑是「我有目标→我制定规范→我推行规范→天下被治理」；庄子的治理逻辑是「我游心于淡→我顺物自然→我无容私焉→天下自然治」。不是「我治天下」，而是「天下自治」——因为万物各有其自然本性，只要不去干扰它，它自己就会运行得好。「无容私焉」是这四句的关键——不是没有作为，而是没有私意。"}]}),n[13]||(n[13]=i("h2",{id:"四、阳子居见老聃·明王之治·立乎不测",tabindex:"-1"},[e("四、阳子居见老聃·明王之治·立乎不测 "),i("a",{class:"header-anchor",href:"#四、阳子居见老聃·明王之治·立乎不测","aria-label":'Permalink to "四、阳子居见老聃·明王之治·立乎不测"'},"​")],-1)),n[14]||(n[14]=i("h3",{id:"原文-3",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-3","aria-label":'Permalink to "原文"'},"​")],-1)),t(a,{sections:u,glossary:p,"default-mode":"classic","aria-label":"应帝王·明王之治 原文"}),n[15]||(n[15]=i("h3",{id:"生僻字词-3",tabindex:"-1"},[e("生僻字词 "),i("a",{class:"header-anchor",href:"#生僻字词-3","aria-label":'Permalink to "生僻字词"'},"​")],-1)),t(s,{items:[{term:"阳子居",pinyin:["yáng","zǐ","jū"],meaning:"人名，即杨朱，道家人物。"},{term:"老聃",pinyin:["lǎo","dān"],meaning:"即老子。聃：耳大垂肩之意。"},{term:"向疾强梁",pinyin:["xiàng","jí","qiáng","liáng"],meaning:"向：志向；疾：迅速；强梁：刚强有力。志向迅猛、刚强有力。"},{term:"物彻疏明",pinyin:["wù","chè","shū","míng"],meaning:"彻：通达；疏明：疏朗明察。对事物通达明察。"},{term:"学道不倦",pinyin:["xué","dào","bù","juàn"],meaning:"勤奋好学，永不懈怠。"},{term:"胥易技系",pinyin:["xū","yì","jì","xì"],meaning:"胥易：相互轻视；技系：被技能所束缚。被才技所束缚、相互较量。"},{term:"劳形怵心",pinyin:["láo","xíng","chù","xīn"],meaning:"怵：恐惧、紧张。劳累形体、紧张内心。"},{term:"有莫举名",pinyin:["yǒu","mò","jǔ","míng"],meaning:"有所作为却没有人能给它命名。一旦可以被命名（「这是仁政」），就已经是有为了。"},{term:"使物自喜",pinyin:["shǐ","wù","zì","xǐ"],meaning:"让万物各自欢喜，各得其所。不是让万物按照我的标准欢喜，而是让万物按照它们自己的本性欢喜。"}]}),n[16]||(n[16]=i("h3",{id:"核心句引读-3",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),t(r,{title:"明王之治：功盖天下而似不自己",subtitle:"明王，不是最强的统治者，而是那个让天下感觉不到「被统治」的人。",lines:[{text:"有人于此，向疾强梁，物彻疏明，学道不倦，如是者，可比明王乎？",tone:"贤人",guide:"阳子居描述的这个人，是一个儒家理想人格的完美版本：向疾强梁（志向远大、意志刚强）、物彻疏明（对事物通达明察）、学道不倦（勤奋好学，永不懈怠）。这三点，几乎涵盖了儒家对「贤人」的全部要求——这样的人，可以比得上明王吗？老子的回答，只有一个字：於。唉。"},{text:"是於圣人也，胥易技系，劳形怵心者也。且也虎豹之文来田，猨狙之便执嫠之狗来藉。",tone:"技系",guide:"老子的判断，极为犀利：这样的人，对于圣人来说——是被技能所束缚、劳累形体、紧张内心的人。向疾强梁——是执着于「强」；物彻疏明——是执着于「明」；学道不倦——是执着于「学」。每一种「优点」，在老子看来，都是一种执着，都是一种「技系」——被自己的才能所束缚。老子用三个动物来比喻：虎豹因为花纹美丽招来猎人；猿猴因为身手灵便被捕来服役；猎狗因为善于捕猎被牵来使用。它们的「优点」，正是它们被利用、被束缚的原因。这不是说才能是坏的，而是说：执着于才能，才能就变成了束缚。"},{text:"明王之治：功盖天下而似不自己，化贷万物而民弗恃。有莫举名，使物自喜。立乎不测，而游于无有者也。",tone:"明王",guide:"阳子居被震动，恭敬地问：那明王之治是什么？老子给出了《应帝王》中最完整的正面答案，四组对句：功盖天下而似不自己——做了一切，却不以「做了」自居（这与《大宗师》道的「赍万物而不为义」完全一致）；化贷万物而民弗恃——给予了一切，却让人感觉不到「被给予」（最好的给予，是让接受者感觉那是自然而然的）；有莫举名——有所作为，却没有人能给它命名（一旦可以被命名，就已经是有为了）；使物自喜——让万物各自欢喜，各得其所（不是让万物按照我的标准欢喜，而是让万物按照它们自己的本性欢喜）。立乎不测，而游于无有者也——立身于深不可测之处，游于无形无迹之境。明王，不是最强的统治者，而是那个让天下感觉不到「被统治」的人。"}]}),n[17]||(n[17]=i("h2",{id:"五、列子·季咸·壶子四示",tabindex:"-1"},[e("五、列子·季咸·壶子四示 "),i("a",{class:"header-anchor",href:"#五、列子·季咸·壶子四示","aria-label":'Permalink to "五、列子·季咸·壶子四示"'},"​")],-1)),n[18]||(n[18]=i("h3",{id:"原文-4",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-4","aria-label":'Permalink to "原文"'},"​")],-1)),t(a,{sections:x,glossary:b,"default-mode":"classic","aria-label":"应帝王·壶子四示 原文"}),n[19]||(n[19]=i("h3",{id:"生僻字词-4",tabindex:"-1"},[e("生僻字词 "),i("a",{class:"header-anchor",href:"#生僻字词-4","aria-label":'Permalink to "生僻字词"'},"​")],-1)),t(s,{items:[{term:"季咸",pinyin:["jì","xián"],meaning:"人名，郑国神巫。"},{term:"列子",pinyin:["liè","zǐ"],meaning:"道家人物，郑国人。"},{term:"心醉",pinyin:["xīn","zuì"],meaning:"心神迷醉、折服。"},{term:"壶子",pinyin:["hú","zǐ"],meaning:"列子之师，得道者。"},{term:"以道与世亢",pinyin:["kàng"],meaning:"亢：对抗、炫耀。用道来与世人对抗炫耀。"},{term:"湿灰",pinyin:["shī","huī"],meaning:"湿润的灰烬，喻生机将灭。"},{term:"地文",pinyin:["dì","wén"],meaning:"大地的纹理，喻静止深厚、不动如地。"},{term:"杜德机",pinyin:["dù","dé","jī"],meaning:"杜：封闭；德机：德性的生机。封闭了德性的生机（不显露）。"},{term:"天壤",pinyin:["tiān","rǎng"],meaning:"天地之间充盈的生气，喻生机勃发。"},{term:"机发于踵",pinyin:["jī","fā","yú","zhǒng"],meaning:"生机从脚跟发出（深沉的生命力）。踵：脚跟。"},{term:"太冲莫胜",pinyin:["tài","chōng","mò","shèng"],meaning:"太冲：极度冲和；莫胜：无所偏胜。冲和到极致，无所偏倚。"},{term:"衡气机",pinyin:["héng","qì","jī"],meaning:"衡：平衡；气机：气的运动。气机平衡，无所偏倚。"},{term:"未始出吾宗",pinyin:["wèi","shǐ","chū","wú","zōng"],meaning:"从未离开过道的本体。宗：根本、本体。壶子第四示，也是《应帝王》全篇的核心。"},{term:"虚而委蛇",pinyin:["xū","ér","wēi","yí"],meaning:"虚：虚空；委蛇：随顺曲折、无固定形态。虚空而随顺流动。"},{term:"弟靡",pinyin:["dì","mí"],meaning:"随风倒伏的草。喻随顺无定形。"},{term:"雕琢复朴",pinyin:["diāo","zhuó","fù","pǔ"],meaning:"去除雕琢，回归朴素本真。"}]}),n[20]||(n[20]=i("h3",{id:"核心句引读-4",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),t(r,{title:"未始出吾宗——从未离开过道的本体",subtitle:"无为的最高境界：不是做了什么，而是从未离开过那个本体。",lines:[{text:"始吾以夫子之道为至矣，则又有至焉者矣。",tone:"比较",guide:"列子见到季咸，心神迷醉——我原以为老师的道是最高的，没想到还有更高的！这句话，暴露了列子此刻的根本问题：他在比较——比较谁的道更高。一个真正得道的人，不会去比较道的高下——因为道是不可比较的，能被比较的，都还不是道本身，而是道的「表现」。列子被季咸的神异技能所折服，说明他还停留在道的外在表现上，还没有触及道的内在实质。"},{text:"吾与汝既其文，未既其实。而固得道与？众雌而无雄，而又奚卵焉！",tone:"雌雄",guide:"壶子的判断，是全段最深的一句话：我教给你的，你学完了文辞，但没有穷尽实质。你真的得道了吗？众雌而无雄，而又奚卵焉！——全是阴柔（外在的形式），没有阳刚（内在的实质）——怎么能孵出结果？这个比喻极为精准：雌——外在的形式、文辞、表现——可以被看见、被学习；雄——内在的实质、生命力、道的本体——无法被直接传授。只有雌没有雄，就像只有蛋壳没有受精——永远孵不出生命。列子学了道的所有外在形式，但那个内在的「雄」——道的实质——不是学来的，是「得」来的。"},{text:"乡吾示之以未始出吾宗。吾与之虚而委蛇，不知其谁何，因以为弟靡，因以为波流，故逃也。",tone:"四示",guide:"这是四示中最深的一示，也是最关键的：前三示，壶子还在「示」某种状态——地文（静）、天壤（生）、太冲（衡）——这些，季咸还能勉强捕捉到某种印象。第四示，壶子什么都没有「示」——他回到了道的本体，虚而委蛇，没有任何固定的样子，没有任何可以被捕捉的迹象。季咸面对的，是一个完全无迹可循的存在——不是死，不是生，不是稳定，不是不稳定——什么都不是，什么都可以是。这让季咸彻底崩溃——自失而走。「未始出吾宗」——这五个字，是《应帝王》全篇的核心：从未离开过道的本体。前三示，壶子是在「展示」——有意识地呈现某种状态；第四示，壶子什么都没做——他只是在道的本体里，虚而委蛇。这就是无为的最高境界：不是做了什么，而是从未离开过那个本体。"},{text:"然后列子自以为未始学而归。三年不出，为其妻爨，食豕如食人，于事无与亲。雕琢复朴，块然独以其形立。纷而封哉，一以是终。",tone:"复朴",guide:"壶子四示之后，列子的转变——自以为未始学（认为自己从来没有真正学过道。这不是自我否定，而是真正的开始：只有放下「我已经学了」的执着，才能真正开始），三年不出（不再出去炫耀道、与世人对抗），为其妻爨（为妻子烧火做饭——回到最平凡的日常），食豕如食人（喂猪如同喂人——无差别对待），于事无与亲（对任何事都不特别执着亲近），雕琢复朴（去除一切雕琢，回归朴素本真）。这是《应帝王》对「真人」最日常的描述：不是在云端，而是在厨房，在猪圈，在柴火旁。列子的转变，不是飞升成仙，不是得道显圣，而是回家烧饭，喂猪，三年不出门。道，落实在最平凡的日常里。"}]}),n[21]||(n[21]=i("h2",{id:"六、至人用心若镜·应而不藏",tabindex:"-1"},[e("六、至人用心若镜·应而不藏 "),i("a",{class:"header-anchor",href:"#六、至人用心若镜·应而不藏","aria-label":'Permalink to "六、至人用心若镜·应而不藏"'},"​")],-1)),n[22]||(n[22]=i("h3",{id:"原文-5",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-5","aria-label":'Permalink to "原文"'},"​")],-1)),t(a,{sections:z,glossary:c,"default-mode":"classic","aria-label":"应帝王·至人若镜 原文"}),n[23]||(n[23]=i("h3",{id:"生僻字词-5",tabindex:"-1"},[e("生僻字词 "),i("a",{class:"header-anchor",href:"#生僻字词-5","aria-label":'Permalink to "生僻字词"'},"​")],-1)),t(s,{items:[{term:"名尸",pinyin:["míng","shī"],meaning:"尸：主持、承担。名声的承担者（执着于名）。"},{term:"谋府",pinyin:["móu","fǔ"],meaning:"府：储藏处。谋略的储藏库（执着于谋）。"},{term:"事任",pinyin:["shì","rèn"],meaning:"事务的承担者（执着于事）。"},{term:"知主",pinyin:["zhī","zhǔ"],meaning:"知识的主人（执着于知）。"},{term:"体尽无穷",pinyin:["tǐ","jìn","wú","qióng"],meaning:"体：体悟、融入。融入无穷无尽的道中，没有边界。"},{term:"游无朕",pinyin:["yóu","wú","zhèn"],meaning:"游于无迹可寻之境。朕：迹象、征兆。"},{term:"无见得",pinyin:["wú","jiàn","dé"],meaning:"不显露有所得的样子。"},{term:"亦虚而已",pinyin:["yì","xū","ér","yǐ"],meaning:"也只是虚空而已（虚是道的本质）。虚，才能容纳一切；虚，才能回应一切。"},{term:"若镜",pinyin:["ruò","jìng"],meaning:"像镜子一样。至人的心，像镜子一样。"},{term:"不将不逆",pinyin:["bù","jiāng","bù","nì"],meaning:"将：送走、追随；逆：迎接、强求。不送走（不执着于离去的），不迎接（不执着于到来的）。"},{term:"应而不藏",pinyin:["yìng","ér","bù","cáng"],meaning:"回应而不留存。镜子如实回应眼前的一切，但不把任何东西留在镜子里。"},{term:"胜物而不伤",pinyin:["shèng","wù","ér","bù","shāng"],meaning:"超越万物而不受伤害。因为没有执着，所以万物无法伤他。"}]}),n[24]||(n[24]=i("h3",{id:"核心句引读-5",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-5","aria-label":'Permalink to "核心句引读"'},"​")],-1)),t(r,{title:"至人之用心若镜，不将不逆，应而不藏",subtitle:"不是没有，而是如实；不是冷漠，而是不执着；不是空洞，而是虚而能应。",lines:[{text:"无为名尸，无为谋府，无为事任，无为知主。",tone:"四无为",guide:"四个「无为」，是《应帝王》对「无为」最具体的操作定义：无为名尸（不做名声的承担者，不执着于名）、无为谋府（不做谋略的储藏库，不执着于谋）、无为事任（不做事务的承担者，不执着于事）、无为知主（不做知识的主人，不执着于知）。名、谋、事、知——这四样，恰好是「有为之治」的四根支柱。四个「无为」，是对前四段所有「有为」的直接回应。"},{text:"至人之用心若镜，不将不逆，应而不藏，故能胜物而不伤。",tone:"若镜",guide:"这是《应帝王》全篇最重要的一句话，也是内篇七篇的终极总结：至人的心，像镜子一样。镜子的三个特性：不将——不送走——镜子不会追着离开的东西跑，东西走了，镜子里就没有了；不逆——不迎接——镜子不会主动迎接到来的东西，东西来了，镜子如实呈现；应而不藏——回应而不留存——镜子如实回应眼前的一切，但不把任何东西留在镜子里。故能胜物而不伤——正因为如此，至人能够超越万物而不受伤害——因为他没有执着，所以万物无法伤他；因为他如实回应，所以万物在他这里各得其所。镜子，是《应帝王》对「无为」最完美的比喻：不是没有，而是如实；不是冷漠，而是不执着；不是空洞，而是虚而能应。"}]}),n[25]||(n[25]=i("h2",{id:"七、浑沌之死·内篇终章",tabindex:"-1"},[e("七、浑沌之死·内篇终章 "),i("a",{class:"header-anchor",href:"#七、浑沌之死·内篇终章","aria-label":'Permalink to "七、浑沌之死·内篇终章"'},"​")],-1)),n[26]||(n[26]=i("h3",{id:"原文-6",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-6","aria-label":'Permalink to "原文"'},"​")],-1)),t(a,{sections:w,glossary:j,"default-mode":"classic","aria-label":"应帝王·浑沌之死 原文"}),n[27]||(n[27]=i("h3",{id:"生僻字词-6",tabindex:"-1"},[e("生僻字词 "),i("a",{class:"header-anchor",href:"#生僻字词-6","aria-label":'Permalink to "生僻字词"'},"​")],-1)),t(s,{items:[{term:"儵",pinyin:["shū"],meaning:"南海之帝，迅疾之意。"},{term:"忽",pinyin:["hū"],meaning:"北海之帝，急速之意。儵与忽合：迅速、有为。"},{term:"浑沌",pinyin:["hùn","dùn"],meaning:"中央之帝，混沌未分之意。道的本体象征。"},{term:"待之甚善",pinyin:["dài","zhī","shèn","shàn"],meaning:"浑沌对待儵与忽非常善待。道对一切有为，都是善待的，包容的。"},{term:"七窍",pinyin:["qī","qiào"],meaning:"眼二、耳二、鼻二、口一，共七窍。"},{term:"视听食息",pinyin:["shì","tīng","shí","xī"],meaning:"看、听、吃、呼吸。人的基本感官功能。"},{term:"尝试凿之",pinyin:["cháng","shì","záo","zhī"],meaning:"试着为他凿开七窍。"}]}),n[28]||(n[28]=i("h3",{id:"核心句引读-6",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-6","aria-label":'Permalink to "核心句引读"'},"​")],-1)),t(r,{title:"日凿一窍，七日而浑沌死",subtitle:"善意，不能成为有为的借口——善意的有为，同样会杀死本真。",lines:[{text:"儵与忽时相与遇于浑沌之地，浑沌待之甚善。",tone:"三帝",guide:"三位帝王的名字，本身就是寓意：儵——迅疾，南海，有为的速度；忽——急速，北海，有为的急促；浑沌——混沌未分，中央，道的本体。儵与忽——两个「有为」的象征，经常在浑沌的地方相遇，而浑沌对他们待之甚善——道对一切有为，都是善待的，包容的。"},{text:"儵与忽谋报浑沌之德，曰：人皆有七窍以视听食息，此独无有，尝试凿之。",tone:"善意",guide:"儵与忽要报答浑沌的善待——这是善意的，不是恶意的。他们的逻辑：人都有七窍，用来看、听、吃、呼吸——浑沌没有七窍，是一种缺陷——我们来帮他凿开，这是好事。这个逻辑，正是《应帝王》全篇所批判的有为之治的根本逻辑：我知道什么是好的——我要把我认为好的，给予你——这是我对你的善意。以己出经式义度——是这个逻辑；藏仁以要人——是这个逻辑；儵与忽凿浑沌——还是这个逻辑。善意，不能成为有为的借口。"},{text:"日凿一窍，七日而浑沌死。",tone:"终章",guide:"这是内篇七篇的最后一句话——也是整部《庄子》内篇最震撼的结尾。每天凿一个窍，七天，浑沌死了。没有愤怒，没有抗争，没有悲剧性的呐喊——只是平静地陈述：浑沌死了。为什么浑沌死了？浑沌是混沌未分的道的本体——它的本质，是无分别、无形式、无窍——正是这个「无」，让它能够容纳一切，待之甚善。七窍，是分别的开始——有了眼，就有了「看见」与「看不见」的分别；有了耳，就有了「听见」与「听不见」的分别——每凿一窍，浑沌就多一种分别；七窍凿完，分别完成，浑沌死了。儵与忽以为在给予，实际上在剥夺——剥夺的，正是浑沌最根本的东西：那个混沌未分的本真。这是《应帝王》对「有为」最终极的寓言：有为，不是坏意，而是善意——但善意的有为，同样会杀死本真。浑沌之死，是内篇七篇的终点，也是庄子留给所有读者的最后一个问题：你是儵与忽，还是浑沌？你在凿别人的七窍，还是守住自己的浑沌？"}]}),n[29]||(n[29]=d("",45))])}}});export{G as __pageData,S as default};
